var e={ENAV:{nome:`ENAV`,cor:`#1E40AF`},CESPE:{nome:`CESPE/Cebraspe`,cor:`#991B1B`},FCC:{nome:`FCC`,cor:`#166534`},VUNESP:{nome:`VUNESP`,cor:`#7C2D12`},AVAMEC:{nome:`AVAMEC`,cor:`#581C87`},CRMV:{nome:`CRMV`,cor:`#0E7490`},UFMG:{nome:`UFMG`,cor:`#4338CA`},UNESP:{nome:`UNESP`,cor:`#B45309`},USP:{nome:`USP`,cor:`#0F766E`},UFRRJ:{nome:`UFRRJ`,cor:`#BE185D`},MAPA:{nome:`MAPA`,cor:`#B91C1C`},UFMT:{nome:`UFMT`,cor:`#6D28D9`},UFBA:{nome:`UFBA`,cor:`#0369A1`},UFPE:{nome:`UFPE`,cor:`#15803D`},UFPR:{nome:`UFPR`,cor:`#A16207`},UFRGS:{nome:`UFRGS`,cor:`#9333EA`},UFRPE:{nome:`UFRPE`,cor:`#DC2626`}},t={concurso:{nome:`Concurso Público`,cor:`#1E40AF`},residencia:{nome:`Residência Veterinária`,cor:`#9333EA`},enav:{nome:`ENAV`,cor:`#DC2626`},crmv:{nome:`Exame CRMV`,cor:`#0D9488`},pos:{nome:`Pós-Graduação`,cor:`#D97706`}},n={clinica_bovina:{nome:`Clínica Bovina`,eixo:`clin`},clinica_equina:{nome:`Clínica Equina`,eixo:`clin`},clinica_ovina:{nome:`Clínica Ovina`,eixo:`clin`},clinica_caprina:{nome:`Clínica Caprina`,eixo:`clin`},clinica_suina:{nome:`Clínica Suína`,eixo:`clin`},emergencias_ga:{nome:`Emergências em Grandes Animais`,eixo:`clin`},doencas_infecciosas_ga:{nome:`Doenças Infecciosas`,eixo:`clin`},doencas_metabolicas_ga:{nome:`Doenças Metabólicas`,eixo:`clin`},parasitoses_ga:{nome:`Parasitoses`,eixo:`clin`},nutricao_ga:{nome:`Nutrição de Grandes Animais`,eixo:`prod`},reproducao_ga:{nome:`Reprodução de Grandes Animais`,eixo:`prod`},cirurgia_ga:{nome:`Cirurgia de Grandes Animais`,eixo:`clin`},manejo_sanitario_ga:{nome:`Manejo Sanitário`,eixo:`prod`},patologia_ga:{nome:`Patologia de Grandes Animais`,eixo:`pre`},legislacao_ga:{nome:`Legislação Sanitária`,eixo:`pre`}},r=[{id:`cga-001`,banca:`ENAV`,ano:2023,prova:`ENAV — Clínica de Grandes Animais 2023`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Exame clínico bovino`,dificuldade:`basico`,enunciado:`No exame clínico de um bovino adulto, os parâmetros fisiológicos normais são:`,alternativas:[`Frequência cardíaca: 60-80 bpm; frequência respiratória: 10-30 mpm; temperatura retal: 37,5-39,5°C`,`Frequência cardíaca: 40-60 bpm; frequência respiratória: 15-30 mpm; temperatura retal: 38,0-39,5°C`,`Frequência cardíaca: 70-90 bpm; frequência respiratória: 20-40 mpm; temperatura retal: 38,5-40,0°C`,`Frequência cardíaca: 30-50 bpm; frequência respiratória: 10-20 mpm; temperatura retal: 37,0-38,5°C`,`Frequência cardíaca: 50-70 bpm; frequência respiratória: 30-50 mpm; temperatura retal: 39,0-40,5°C`],resposta_correta:`A`,explicacao:`Os parâmetros fisiológicos normais de bovinos adultos são: FC 60-80 bpm, FR 10-30 mpm e temperatura retal 38,0-39,5°C. Valores fora desses indicam alterações clínicas como febre, taquicardia ou taquipneia que devem ser investigadas.`},{id:`cga-002`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário 2022`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Timpanismo ruminal`,dificuldade:`medio`,enunciado:`Um bovino de corte de 18 meses apresenta distensão abdominal acentuada do flanco esquerdo, desconforto respiratório e salivação excessiva após ingestão de pastagem jovem de trevo. O timpanismo espumoso ocorre pela formação de espuma estável no rúmen, dificultando a eructação, e deve ser tratado com agentes antiespumantes como poloxaleno ou óleo mineral.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O timpanismo espumoso ocorre pela formação de espuma estável no rúmen, dificultando a eructação, e deve ser tratado com agentes antiespumantes como poloxaleno ou óleo mineral.`,explicacao:`O timpanismo espumoso é causado por proteínas solúveis e polissacarídeos de pastagens jovens que formam espuma estável no rúmen. O tratamento de primeira escolha é a administração de agentes antiespumantes (poloxaleno, dimeticona, óleo mineral 500-1000 mL).`},{id:`cga-003`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário MAPA 2021`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Deslocamento de abomaso`,dificuldade:`medio`,enunciado:`Sobre o deslocamento de abomaso (DA) em vacas leiteiras, assinale a alternativa CORRETA:`,alternativas:[`O deslocamento à direita (DAD) é mais frequente que o deslocamento à esquerda (DAE).`,`O DAE ocorre tipicamente no pós-parto e cursa com pings metarionais característicos no flanco esquerdo, entre a fossa paralombar e a costela.`,`O diagnóstico do DAD é feito exclusivamente por ultrassonografia.`,`A omentopexia é o único tratamento cirúrgico disponível para o DAE.`,`O DAE não está associado a doenças de vaca-cola.`],resposta_correta:`B`,explicacao:`O DAE é a afecção cirúrgica mais comum do abomaso em vacas leiteiras de alta produção, ocorrendo tipicamente no pós-parto (2-6 semanas). O diagnóstico é feito pela percussão/auscultação do ping metarional no flanco esquerdo.`},{id:`cga-004`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Veterinário 2023`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Pneumonia bovina`,dificuldade:`medio`,enunciado:`Bezerros de 3 meses apresentam tosse, corrimento nasal mucopurulento, febre (40,5°C) e dispneia. Ao exame auscultatório há áreas de crepitação e sons bronquiais. O agente mais comumente envolvido na pneumonia complexa bovina é:`,alternativas:[`Pasteurella multocida e Mannheimia haemolytica`,`Mycoplasma bovis e Arcanobacterium pyogenes`,`Mannheimia haemolytica e Histophilus somni`,`Bovine Respiratory Syncytial Virus (BRSV) e Pasteurella multocida`,`Todos os anteriores podem estar envolvidos, sendo M. haemolytica o principal agente bacteriano primário`],resposta_correta:`E`,explicacao:`A pneumonia bovina (complexo respiratório bovino) é multifatorial, envolvendo vírus (BRSV, IBR, BVD, PI3) e bactérias (M. haemolytica, P. multocida, H. somni, M. bovis). M. haemolytica é o principal agente bacteriano primário, causando pneumonia fibrinonecrosante.`},{id:`cga-005`,banca:`UFMG`,ano:2020,prova:`UFMG — Residência Clínica de Grandes Animais 2020`,tipo:`residencia`,topico:`clinica_bovina`,subtopico:`Cetose bovina`,dificuldade:`dificil`,enunciado:`Uma vaca Holandesa de 4ª lactação, 10 dias pós-parto, apresenta queda de produção de leite, apetite caprichoso, hálito cetônico e perda de peso. O diagnóstico de cetose subclínica é confirmado quando os níveis séricos de β-hidroxibutirato (BHBA) estão:`,alternativas:[`Acima de 0,5 mmol/L`,`Acima de 1,0 mmol/L`,`Acima de 1,2 mmol/L`,`Acima de 1,4 mmol/L`,`Acima de 2,0 mmol/L`],resposta_correta:`C`,explicacao:`A cetose subclínica é diagnosticada com BHBA entre 1,0-1,4 mmol/L, sendo 1,2 mmol/L o valor de corte mais aceito. Valores acima de 1,4 mmol/L indicam cetose clínica. O tratamento inclui propilenoglicol (300-500 mL/dia via oral) e, nos casos graves, dextrose 50% IV.`},{id:`cga-006`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Raiva bovina`,dificuldade:`medio`,enunciado:`Sobre a raiva bovina, assinale a alternativa CORRETA:`,alternativas:[`A raiva bovina é transmitida exclusivamente por morcegos hematófagos (Desmodus rotundus) no Brasil.`,`Os bovinos com raiva paralítica apresentam dificuldade de locomoção, ataxia dos membros pélvicos, prolapso do terceiro pálpebra e evolução para decúbito em 3 a 5 dias.`,`O diagnóstico definitivo da raiva bovina é feito por sorologia (ELISA) em amostras de sangue.`,`A raiva bovina tem tratamento eficaz com soro antirrábico associado a corticoides.`,`A vacinação antirrábica em bovinos é contraindicada pelo MAPA.`],resposta_correta:`B`,explicacao:`A raiva paralítica bovina apresenta dificuldade de locomoção, ataxia pélvica, prolapso do terceiro pálpebra e evolução para decúbito. O diagnóstico é por imunofluorescência direta em tecido encefálico. Não há tratamento. A transmissão pode ser por morcegos hematófagos ou por carnívoros.`},{id:`cga-007`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Doença de Johne`,dificuldade:`dificil`,enunciado:`Sobre a paratuberculose (Doença de Johne) em bovinos, é CORRETO afirmar:`,alternativas:[`Acomete exclusivamente bovinos e não tem importância zoonótica.`,`Causada por Mycobacterium avium subsp. paratuberculosis, apresenta período de incubação prolongado (2-10 anos), diarreia crônica intermitente, perda de peso progressiva e edema submandibular.`,`O diagnóstico de rotina é feito por cultura fecal em meio Löwenstein-Jensen, com resultado em 48 horas.`,`O tratamento com macrolídeos (claritromicina) é eficaz e recomendado.`,`A vacinação elimina a infecção do rebanho em 5 anos.`],resposta_correta:`B`,explicacao:`A paratuberculose é causada por MAP, com longo período de incubação. Os sinais clínicos incluem diarreia crônica, perda de peso progressiva, edema submandibular (bottle jaw) e queda de produção. O diagnóstico é por ELISA ou PCR, com cultura levando 8-16 semanas. Não há tratamento eficaz.`},{id:`cga-008`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso 2020`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Retenção de placenta`,dificuldade:`basico`,enunciado:`A retenção de placenta em bovinos é definida como a não expulsão das membranas fetais em até:`,alternativas:[`3 horas após o parto`,`6 horas após o parto`,`8 horas após o parto`,`12 horas após o parto`,`24 horas após o parto`],resposta_correta:`D`,explicacao:`Em bovinos, a retenção de placenta é diagnosticada quando as membranas fetais não são expulsas em até 24 horas após o parto. Os fatores de risco incluem parto distócico, gemelar, aborto, hipocalcemia, cesariana e indução prematura do parto.`},{id:`cga-009`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário 2023`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Mastite bovina`,dificuldade:`medio`,enunciado:`Sobre a mastite subclínica em rebanhos leiteiros, é CORRETO:`,alternativas:[`O California Mastitis Test (CMT) substitui a contagem de células somáticas (CCS) individual.`,`A mastite subclínica é causada predominantemente por patógenos contagiosos (S. aureus, S. agalactiae), transmitidos durante a ordenha, e o controle se baseia em ordenha higiênica e tratamento de vacas secas.`,`A CCS individual acima de 200.000 células/mL é considerada normal para vacas em lactação.`,`O tratamento sistêmico com antibióticos é indicado para todas as mastites subclínicas.`,`A mastite subclínica não afeta a produção de leite.`],resposta_correta:`B`,explicacao:`Os patógenos contagiosos predominam na mastite subclínica e são transmitidos durante a ordenha. O controle inclui pré-dipping, pós-dipping, tratamento de vaca seca e descarte de vacas crônicas. CCS > 200.000/mL indica mastite subclínica.`},{id:`cga-010`,banca:`UNESP`,ano:2022,prova:`UNESP — Residência 2022`,tipo:`residencia`,topico:`clinica_bovina`,subtopico:`Broncopneumonia enzoótica`,dificuldade:`basico`,enunciado:`Na broncopneumonia enzoótica de bezerros, o achado clínico mais característico ao exame físico é:`,alternativas:[`Diarréia aquosa profusa e desidratação`,`Tosse, corrimento nasal e alterações pulmonares à auscultação (crepitações, sons bronquiais)`,`Edema submandibular e linfadenomegalia`,`Icterícia e hemoglobinúria`,`Úlceras bucais e erosões no palato`],resposta_correta:`B`,explicacao:`A broncopneumonia enzoótica caracteriza-se por tosse, corrimento nasal (inicialmente seroso, depois mucopurulento), febre e alterações auscultatórias pulmonares como crepitações e sons bronquiais nas regiões anteroventrais dos pulmões.`},{id:`cga-011`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Leucose enzoótica bovina`,dificuldade:`dificil`,enunciado:`Sobre a leucose enzoótica bovina (LEB), causada pelo Vírus da Leucemia Bovina (BLV), assinale a alternativa CORRETA:`,alternativas:[`A maioria dos bovinos infectados desenvolve linfossarcoma.`,`A maioria dos bovinos infectados permanece clinicamente saudável (forma linfocitária persistente), e apenas 1-5% desenvolve linfossarcoma.`,`O diagnóstico é feito exclusivamente por hemograma (linfocitose).`,`O BLV infecta apenas bovinos e não há evidência de transmissão vertical.`,`O tratamento com interferon bovino é eficaz na eliminação do vírus.`],resposta_correta:`B`,explicacao:`A maioria dos bovinos infectados pelo BLV permanece assintomática ou com linfocitose persistente. Apenas 1-5% desenvolve linfossarcoma. O diagnóstico é por ELISA ou AGID. A transmissão ocorre por contato direto (sangue, leite, colostro), iatrogenicamente e verticalmente.`},{id:`cga-012`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal Agropecuário 2023`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Febre aftosa`,dificuldade:`medio`,enunciado:`Sobre a febre aftosa em bovinos, assinale a alternativa CORRETA:`,alternativas:[`O período de incubação é de 1 a 3 dias.`,`As vesículas ocorrem exclusivamente na boca e não nos cascos.`,`A mortalidade em bovinos adultos é superior a 50%.`,`Os sinais clínicos incluem febre, vesículas na boca, úbere e entre os dedos, seguidas de erosões, sialorreia e claudicação.`,`O vírus da febre aftosa pertence à família Herpesviridae.`],resposta_correta:`D`,explicacao:`A fere aftosa é causada por um Aphthovirus (Picornaviridae), com período de incubação de 2-14 dias. Os sinais incluem febre, vesículas e erosões na cavidade oral, úbere e coronetas, sialorreia e claudicação. A mortalidade em adultos é baixa (<5%), mas alta em bezerros.`},{id:`cga-013`,banca:`USP`,ano:2020,prova:`USP — Pós-Graduação 2020`,tipo:`pos`,topico:`clinica_bovina`,subtopico:`Clostridioses bovinas`,dificuldade:`dificil`,enunciado:`Sobre as clostridioses em bovinos, é INCORRETO afirmar:`,alternativas:[`O carbúnculo sintomático é causado por Clostridium chauvoei e afeta músculos esqueléticos.`,`A enterotoxemia é causada por Clostridium perfringens tipos B, C e D.`,`O tétano é causado por Clostridium tetani e apresenta rigidez muscular progressiva.`,`A edema maligno é causado por Clostridium septicum e ocorre em ferimentos contaminados.`,`A vacinação polivalente (8 ou 9 cepas) não é eficaz na prevenção das clostridioses bovinas.`],resposta_correta:`E`,explicacao:`A vacinação polivalente (8-9 cepas) é altamente eficaz na prevenção das clostridioses bovinas, sendo uma das práticas mais importantes do manejo sanitário. Deve ser feita com reforço anual e nas fêmeas antes do parto para transferência de imunidade passiva aos bezerros.`},{id:`cga-014`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Concurso 2022`,tipo:`concurso`,topico:`clinica_bovina`,subtopico:`Diarreia neonatal`,dificuldade:`basico`,enunciado:`A diarreia neonatal em bezerros é a principal causa de mortalidade nos primeiros 30 dias de vida. Sobre a etiologia, assinale a alternativa CORRETA:`,alternativas:[`Os principais agentes virais são rotavírus e coronavírus, que causam diarreia aquosa e desidratação.`,`A diarreia por E. coli enterotoxigênica ocorre exclusivamente em bezerros acima de 30 dias.`,`Cryptosporidium parvum causa diarreia apenas em bezerros imunossuprimidos.`,`A Salmonella spp. causa diarreia branda autolimitada em neonatos.`,`Os agentes infecciosos nunca atuam de forma simultânea na diarreia neonatal.`],resposta_correta:`A`,explicacao:`Os principais agentes virais da diarreia neonatal são rotavírus (Grupo A) e coronavírus bovino. E. coli enterotoxigênica causa diarreia nos primeiros 4-5 dias. Cryptosporidium é frequente entre 1-3 semanas. Salmonella causa diarreia hemorrágica grave. Coinfecções são comuns.`},{id:`cga-015`,banca:`ENAV`,ano:2023,prova:`ENAV — Clínica Equina 2023`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Cólica equina`,dificuldade:`medio`,enunciado:`Um equino de 8 anos apresenta sudorese profusa, pedalamento, olhar para os flancos e distensão abdominal. Os sinais de dor aguda em cólica equina sugerem:`,alternativas:[`Lesões médias que geralmente requerem tratamento clínico.`,`Lesões graves como deslocamento, torção ou estrangulamento intestinal que frequentemente requerem intervenção cirúrgica.`,`Apenas cólica gasosa que responde ao tratamento com analgésicos.`,`Timpanismo gástrico primário que é sempre autolimitado.`,`Infecção por Parascaris equorum em potros adultos.`],resposta_correta:`B`,explicacao:`Dor aguda intensa (sudorese, pedalamento, decúbito) em equinos adultos sugere lesões graves como deslocamento, torção ou estrangulamento intestinal que frequentemente requerem intervenção cirúrgica. A resposta ao analgésico é temporária e a dor retorna com intensidade.`},{id:`cga-016`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Laminite`,dificuldade:`dificil`,enunciado:`Sobre a laminite (pododermatite) em equinos, assinale a alternativa CORRETA:`,alternativas:[`A laminite é exclusivamente causada por sobrealimentação com concentrados.`,`A fase aguda (estágio de desenvolvimento) dura 24-72 horas e é caracterizada por alteração da perfusão sanguínea laminar, edema e dor.`,`O tratamento da laminite crônica é sempre cirúrgico (tenotomia do tendão profundo do dedo).`,`A rotação da terceira falange é irreversível em todos os casos.`,`A aplicação de gelo nos cascos (crioterapia) é contraindicada na fase aguda.`],resposta_correta:`B`,explicacao:`A laminite aguda tem três fases: desenvolvimento (24-72h), aguda e crônica. Na fase de desenvolvimento ocorre alteração da perfusão sanguínea laminar, edema e separação das lamelas. A crioterapia precoce pode prevenir a progressão.`},{id:`cga-017`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Doença respiratória equina`,dificuldade:`medio`,enunciado:`A obstrução das vias aéreas superiores em equinos pode se manifestar como estridor inspiratório. Sobre a hemiplegia laríngea (roaring), assinale a alternativa CORRETA:`,alternativas:[`Afeta igualmente ambos os lados da laringe.`,`É causada por paralisia do nervo laríngeo recorrente esquerdo, resultando em desvio medial da aritenóide esquerda durante a inspiração.`,`O diagnóstico é exclusivamente clínico, sem necessidade de endoscopia.`,`O tratamento clínico com corticoides reverte completamente a condição.`,`É mais comum em equinos de pequeno porte (ponies).`],resposta_correta:`B`,explicacao:`A hemiplegia laríngea é causada por neuropatia do nervo laríngeo recorrente esquerdo (devido ao seu longo trajeto), resultando em paralisia da aritenóide esquerda. O diagnóstico é por endoscopia durante exercício. O tratamento é cirúrgico (laringoplastia ou tie-back).`},{id:`cga-018`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Anemia infecciosa equina`,dificuldade:`medio`,enunciado:`Sobre a Anemia Infecciosa Equina (AIE), assinale a alternativa CORRETA:`,alternativas:[`A AIE é causada por um retrovírus e os equinos infectados eliminam o vírus rapidamente.`,`A AIE é causada por um lentivírus (família Retroviridae), a infecção é persistente e os equinos infectados tornam-se portadores vitalícios.`,`O diagnóstico de rotina é feito por hemograma completo.`,`O tratamento com antivirais é eficaz na eliminação do vírus.`,`A transmissão ocorre apenas por via aérea.`],resposta_correta:`B`,explicacao:`A AIE é causada por um lentivírus da família Retroviridae. A infecção é persistente e os equinos tornam-se portadores vitalícios. O diagnóstico é por teste de Coggins (AGID) ou ELISA. A transmissão é mecânica por insetos hematófagos (tabanídeos, moscas estáveis).`},{id:`cga-019`,banca:`UFMG`,ano:2022,prova:`UFMG — Residência 2022`,tipo:`residencia`,topico:`clinica_equina`,subtopico:`Mioglobinúria equina`,dificuldade:`dificil`,enunciado:`A mioglobinúria paralítica (rhabdomyolysis) em equinos é caracterizada por:`,alternativas:[`Diarreia profusa e desidratação aguda.`,`Rigidez muscular dos membros posteriores, sudorese, urina escura (cor de café) e dor à palpação muscular.`,`Edema submandibular e linfadenomegalia.`,`Tosse crônica e dispneia.`,`Úlceras gástricas e perda de peso.`],resposta_correta:`B`,explicacao:`A mioglobinúria paralítica caracteriza-se por rigidez muscular progressiva dos membros posteriores, sudorese, urina escura (mioglobinúria), dor à palpação muscular e, nos casos graves, mioglobinúria renal. Está associada a exercício intenso, estresse ou alimentação excessiva com concentrados.`},{id:`cga-020`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Encefalomielite equina`,dificuldade:`medio`,enunciado:`As encefalomielites equinas são causadas por arbovírus. Sobre a Encefalomielite Venezuelana Equina (EVE), assinale a alternativa CORRETA:`,alternativas:[`É transmitida por contato direto entre equinos.`,`É transmitida por mosquitos (Culex e Aedes) e os equinos são hospedeiros amplificadores do vírus.`,`Não afeta seres humanos.`,`O diagnóstico é feito por hemograma.`,`Não existe vacina disponível.`],resposta_correta:`B`,explicacao:`A EVE é transmitida por mosquitos e os equinos são hospedeiros amplificadores do vírus, que também infecta humanos (zoonose). O diagnóstico é por sorologia (ELISA, PRNT). Existem vacinas de vírus vivo modificado e inativado.`},{id:`cga-021`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Piroplasmose equina`,dificuldade:`medio`,enunciado:`A piroplasmose equina é causada por:`,alternativas:[`Babesia caballi e Babesia equi (Theileria equi), transmitidas por carrapatos.`,`Plasmodium falciparum transmitido por mosquitos.`,`Trypanosoma evansi transmitido por moscas tsé-tsé.`,`Anaplasma phagocytophilum transmitido por carrapatos Ixodes.`,`Leishmania spp. transmitida por flebotomíneos.`],resposta_correta:`A`,explicacao:`A piroplasmose equina é causada por Babesia caballi e Theileria equi (antes classificada como Babesia equi), transmitidas por carrapatos dos gêneros Dermacentor, Rhipicephalus e Amblyomma. Os sinais incluem febre, icterícia, anemia hemolítica e hemoglobinúria.`},{id:`cga-022`,banca:`CESPE`,ano:2023,prova:`CESPE — Veterinário 2023`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Úlceras gástricas`,dificuldade:`basico`,enunciado:`Sobre a síndrome da úlcera gástrica equina (SUGE), assinale a alternativa CORRETA:`,alternativas:[`Afeta exclusivamente cavalos de corrida.`,`O diagnóstico definitivo é feito por gastroscopia, que permite visualizar as lesões na mucosa gástrica.`,`O tratamento de primeira escolha é a penicilina oral.`,`A úlcera gástrica em equinos ocorre apenas na região glandular do estômago.`,`O omeprazol não é eficaz no tratamento de úlceras equinas.`],resposta_correta:`B`,explicacao:`A SUGE afeta equinos de todas as atividades. O diagnóstico definitivo é por gastroscopia. O tratamento de primeira escolha é o omeprazol (4 mg/kg VO, 1x/dia por 28 dias). As úlceras ocorrem principalmente na região não glandular (escamosa) do estômago.`},{id:`cga-023`,banca:`UFMT`,ano:2022,prova:`UFMT — Concurso 2022`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Potro neonato`,dificuldade:`dificil`,enunciado:`Um potro neonato apresenta fraqueza, incapacidade de mamar, hipotermia e convulsões. A causa mais provável é:`,alternativas:[`Encefalomielite viral.`,`Septicemia neonatal e falha na transferência de imunidade passiva (FTIP).`,`Infecção por Strongyloides westeri.`,`Enterocolite por Salmonella.`,`Laminite aguda.`],resposta_correta:`B`,explicacao:`Os sinais de fraqueza, incapacidade de mamar, hipotermia e convulsões em potro neonato são sugestivos de septicemia neonatal. A falha na transferência de imunidade passiva (IgG sérica < 800 mg/dL) é o principal fator de risco. O diagnóstico é por hemocultura e dosagem de IgG.`},{id:`cga-024`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário 2020`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Dermatofitose equina`,dificuldade:`basico`,enunciado:`A dermatofitose equina é causada principalmente por:`,alternativas:[`Staphylococcus aureus.`,`Trichophyton mentagrophytes e Microsporum canis.`,`Malassezia pachydermatis.`,`Dermatophilus congolensis.`,`Sarcoptes scabiei.`],resposta_correta:`B`,explicacao:`Os principais agentes da dermatofitose equina são Trichophyton mentagrophytes e Microsporum canis. As lesões são placas alopécicas circulares com descamação. O diagnóstico é por cultivo em meio Sabouraud e lâmpada de Wood. O tratamento inclui antifúngicos tópicos e sistêmicos.`},{id:`cga-025`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso 2023`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Cólica por estase cecal`,dificuldade:`medio`,enunciado:`A cólica por estase cecal em equinos está frequentemente associada a:`,alternativas:[`Infestação por Parascaris equorum.`,`Uso de anti-inflamatórios não esteroidais (AINEs) e desidratação.`,`Exercício excessivo.`,`Infecção por Salmonella.`,`Laminite crônica.`],resposta_correta:`B`,explicacao:`A estase cecal está associada ao uso de AINEs (principalmente fenilbutazona), desidratação, imobilização e mudanças alimentares. Os AINEs podem causar ulcerção cecal e alterar a motilidade intestinal. O diagnóstico é por retificação retal e ultrassonografia transretal.`},{id:`cga-026`,banca:`UFRGS`,ano:2021,prova:`UFRGS — Residência 2021`,tipo:`residencia`,topico:`clinica_equina`,subtopico:`Doença do navicular`,dificuldade:`dificil`,enunciado:`A síndrome do navicular (podotrocleose) em equinos é caracterizada por:`,alternativas:[`Claudicação aguda de membro anterior com edema articular evidente.`,`Claudicação insidiosa bilateral dos membros anteriores, com encurtamento da passada e apoio da pinça.`,`Claudicação de membro posterior com atrofia muscular glútea.`,`Rigidez cervical e torcicolo.`,`Edema de membros posteriores e dermatite.`],resposta_correta:`B`,explicacao:`A síndrome do navicular causa claudicação insidiosa, bilateral e intermitente dos membros anteriores. O cavalo apóia a pinça (ápice do casco) para aliviar a pressão no navicular. O diagnóstico é por anestesia do nervo digital palmar, radiografia e ressonância magnética.`},{id:`cga-027`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso 2022`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Tétano equino`,dificuldade:`medio`,enunciado:`O tétano em equinos é causado por Clostridium tetani. Os sinais clínicos característicos incluem:`,alternativas:[`Diarréia profusa e desidratação.`,`Rigidez muscular progressiva (trismo, opistótonos, membros em "cavalete"), prolapse da terceira pálpebra e hiperestesia.`,`Tosse crônica e corrimento nasal.`,`Icterícia e hemoglobinúria.`,`Edema submandibular e linfadenomegalia.`],resposta_correta:`B`,explicacao:`O tétano equino apresenta rigidez muscular generalizada progressiva, trismo (riso sardônico), opistótonos, prolapse da terceira pálpebra, membros em posição de "cavalete" e hiperestesia. Equinos são os animais mais susceptíveis ao tétano.`},{id:`cga-028`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Concurso 2020`,tipo:`concurso`,topico:`clinica_equina`,subtopico:`Raiva equina`,dificuldade:`basico`,enunciado:`A raiva em equinos apresenta-se predominantemente na forma:`,alternativas:[`Furiosa, com agressividade e mordidas.`,`Paralítica (muda), com dificuldade de deglutição, paralisia dos membros e decúbito.`,`Subclínica, sem sinais evidentes.`,`Cutânea, com lesões dermatológicas.`,`Gastrointestinal, com diarréia e vômitos.`],resposta_correta:`B`,explicacao:`A raiva em equinos apresenta-se predominantemente na forma paralítica (muda), com dificuldade de deglutição, paralisia progressiva dos membros, decúbito e morte em 3-7 dias. A forma furiosa é menos comum em equinos.`},{id:`cga-029`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Exame clínico ovino`,dificuldade:`basico`,enunciado:`No exame clínico de ovinos adultos, os parâmetros fisiológicos normais são:`,alternativas:[`FC: 70-90 bpm; FR: 12-20 mpm; temperatura: 38,5-40,0°C`,`FC: 40-60 bpm; FR: 10-30 mpm; temperatura: 38,0-39,5°C`,`FC: 60-80 bpm; FR: 15-30 mpm; temperatura: 37,5-39,0°C`,`FC: 80-120 bpm; FR: 20-40 mpm; temperatura: 39,0-40,5°C`,`FC: 50-70 bpm; FR: 10-15 mpm; temperatura: 37,0-38,5°C`],resposta_correta:`A`,explicacao:`Os parâmetros fisiológicos normais de ovinos adultos são: FC 70-90 bpm, FR 12-20 mpm e temperatura retal 38,5-40,0°C. A temperatura corporal dos ovinos é ligeiramente superior à dos bovinos.`},{id:`cga-030`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Clostridiose ovina`,dificuldade:`medio`,enunciado:`Ovinos em pastejo intensivo apresentam morte súbita, abdômen distendido e hemorragias subcutâneas. O diagnóstico mais provável é:`,alternativas:[`Enterotoxemia por Clostridium perfringens tipo D.`,`Pneumonia por Mannheimia haemolytica.`,`Intoxicação por plantas hepatotóxicas.`,`Hipocalcemia pós-parto.`,`Anemia parasitária.`],resposta_correta:`A`,explicacao:`A enterotoxemia por C. perfringens tipo D (clostridiose) é a causa mais comum de morte súbita em ovinos em pastejo intensivo. A toxina epsilon causa necrose intestinal e encefálica. O diagnóstico é confirmado pela detecção da toxina epsilon no conteúdo intestinal.`},{id:`cga-031`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Cloatro perfringens`,dificuldade:`medio`,enunciado:`Sobre a enterotoxemia em ovinos, causada por Clostridium perfringens, assinale a alternativa CORRETA:`,alternativas:[`Acomete exclusivamente cordeiros lactentes.`,`A vacinação das ovelhas no terço final da gestação proporciona imunidade passiva aos cordeiros por meio do colostro.`,`O tratamento com antibióticos é sempre eficaz mesmo em casos avançados.`,`A doença ocorre apenas em animais em confinamento.`,`O diagnóstico é feito exclusivamente por hemograma.`],resposta_correta:`B`,explicacao:`A vacinação das ovelhas no terço final da gestação (40 e 20 dias antes do parto) proporciona imunidade passiva aos cordeiros por meio do colostro rico em anticorpos anti-toxinas. Esta é a principal medida preventiva.`},{id:`cga-032`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Brucelose ovina`,dificuldade:`medio`,enunciado:`A brucelose ovina é causada por Brucella melitensis. Sobre a epidemiologia e diagnóstico, é CORRETO:`,alternativas:[`A transmissão ocorre exclusivamente por via venérea.`,`Os sinais clínicos incluem aborto no terço final da gestação, orquite em machos e retenção de placenta.`,`O diagnóstico de rotina é feito por cultura em meio seletivo.`,`Não tem importância zoonótica.`,`O tratamento com estreptomicina é eficaz e recomendado.`],resposta_correta:`B`,explicacao:`A brucelose por B. melitensis causa aborto no terço final da gestação, retenção de placenta, orquite em machos e infertilidade. É altamente zoonótica. O diagnóstico é por sorologia (RBPT, SAT, ELISA). Não há tratamento recomendado em animais — descarte é obrigatório.`},{id:`cga-033`,banca:`UFMG`,ano:2020,prova:`UFMG — Concurso 2020`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Scrapie`,dificuldade:`dificil`,enunciado:`Sobre a scrapie (tremedeira) em ovinos, assinale a alternativa CORRETA:`,alternativas:[`É causada por um vírus RNA envelopado.`,`É uma encefalopatia espongiforme transmissível (EET) causada por príon, com período de incubação de 2-5 anos, caracterizada por prurido intenso, ataxia e tremores.`,`O diagnóstico definitivo é feito por sorologia (ELISA).`,`Existe tratamento eficaz com antivirais.`,`Não há suscetibilidade genética associada.`],resposta_correta:`B`,explicacao:`A scrapie é uma EET causada por príon (PrPSc), com longo período de incubação. Os sinais incluem prurido intenso (o animal se esfrega em cercas), ataxia, tremores e perda de peso. A suscetibilidade é determinada pelo polimorfismo do gene PRNP. Não há tratamento.`},{id:`cga-034`,banca:`UNESP`,ano:2022,prova:`UNESP — Concurso 2022`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Cenurose`,dificuldade:`medio`,enunciado:`A cenurose (gid) em ovinos é causada pela forma larvária de:`,alternativas:[`Taenia solium`,`Taenia multiceps (Coenurus cerebralis)`,`Echinococcus granulosus`,`Moniezia expansa`,`Taenia hydatigena`],resposta_correta:`B`,explicacao:`A cenurose é causada por Coenurus cerebralis, a forma larvária de Taenia multiceps. O cisticerco se localiza no SNC, causando sinais neurológicos: andar em círculos, torcicolo, opistótonos e cegueira. O diagnóstico é radiográfico/ultrassonográfico e o tratamento é cirúrgico.`},{id:`cga-035`,banca:`MAPA`,ano:2021,prova:`MAPA — Fiscal Agropecuário 2021`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Raiva ovina`,dificuldade:`basico`,enunciado:`A raiva em ovinos, transmitida por morcegos hematófagos (Desmodus rotundus), apresenta-se clinicamente como:`,alternativas:[`Morte súbita sem sinais premonitórios.`,`Forma paralítica com dificuldade de locomoção, ataxia, prolapso do terceiro pálpebra e evolução para decúbito.`,`Forma furiosa com agressividade intensa.`,`Diarreia crônica e perda de peso.`,`Pneumonia aguda e dispneia.`],resposta_correta:`B`,explicacao:`A raiva em ovinos transmitida por morcegos hematófagos apresenta-se na forma paralítica, com dificuldade de locomoção, ataxia, prolapso do terceiro pálpebra, sialorreia e evolução para decúbito em 3-5 dias.`},{id:`cga-036`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Hipotermia neonatal`,dificuldade:`basico`,enunciado:`A hipotermia neonatal em cordeiros é uma das principais causas de mortalidade. O tratamento inclui:`,alternativas:[`Apenas aquecimento ambiental.`,`Aquecimento gradual (lâmpada infravermelha ou água morna 40°C), glicose oral ou IV e colostro nas primeiras 2 horas de vida.`,`Administração de antibióticos de amplo espectro.`,`Ressuscitação com adrenalina intracardíaca.`,`Exposição ao frio para estimular o reflexo de tremor.`],resposta_correta:`B`,explicacao:`O tratamento da hipotermia neonatal em cordeiros inclui aquecimento gradual (lâmpada infravermelha, água morna 40°C), reposição de glicose (oral ou IV) e oferta imediata de colostro para fornecer energia e imunoglobulinas.`},{id:`cga-037`,banca:`UFPE`,ano:2023,prova:`UFPE — Concurso 2023`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Pasteurelose ovina`,dificuldade:`medio`,enunciado:`A pasteurelose (doença respiratória ovina) é causada principalmente por:`,alternativas:[`Staphylococcus aureus.`,`Mannheimia haemolytica e Bibersteinia trehalosi.`,`Mycoplasma ovipneumoniae como único agente.`,`Pasteurella multocida exclusivamente.`,`Corynebacterium pseudotuberculosis.`],resposta_correta:`B`,explicacao:`A pasteurelose ovina é causada principalmente por Mannheimia haemolytica e Bibersteinia trehalosi (antes Pasteurella trehalosi). A doença é multifatorial, envolvendo estresse, transporte, mudanças climáticas e infecções virais predisponentes.`},{id:`cga-038`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Cascão`,dificuldade:`basico`,enunciado:`O "cascão" ou "dermatite ovina" é causado por:`,alternativas:[`Sarcoptes scabiei.`,`Psoroptes ovis, causando dermatite com crostas espessas, prurido intenso e perda de lã.`,`Linognathus ovillus.`,`Melophagus ovinus.`,`Dermatophilus congolensis.`],resposta_correta:`B`,explicacao:`O "cascão" ou sarna psoróptica é causado por Psoroptes ovis, um ácaro não escavador que causa dermatite com crostas espessas, prurido intenso e perda de lã. O diagnóstico é por raspado de pele. O tratamento inclui avermectinas tópicas ou sistêmicas.`},{id:`cga-039`,banca:`UFPR`,ano:2021,prova:`UFPR — Concurso 2021`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Verminose ovina`,dificuldade:`medio`,enunciado:`A verminose gastrintestinal em ovinos é uma das principais causas de perdas produtivas. O nematódeo mais patogênico é:`,alternativas:[`Haemonchus contortus, que causa anemia e edema submandibular.`,`Trichostrongylus colubriformis, que causa diarreia profusa.`,`Teladorsagia circumcincta, que causa hipoproteinemia.`,`Ostertagia ostertagi, que causa gastrite parasitária.`,`Cooperia punctata, que causa perda de peso.`],resposta_correta:`A`,explicacao:`Haemonchus contortus (barber pole worm) é o nematódeo mais patogênico em ovinos, causando anemia severa, hipoproteinemia e edema submandibular ("bottle jaw"). Uma fêmea pode colocar até 10.000 ovos/dia. O diagnóstico é por EPG e FAMACHA.`},{id:`cga-040`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Concurso 2022`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Toxoplasmose ovina`,dificuldade:`medio`,enunciado:`A toxoplasmose em ovinos, causada por Toxoplasma gondii, pode causar:`,alternativas:[`Apenas infecção subclínica sem consequências reprodutivas.`,`Aborto, natimortos, natimortos mumificados e neonatos fracos.`,`Pneumonia intersticial crônica.`,`Encefalite espongiforme.`,`Dermatite granulomatosa.`],resposta_correta:`B`,explicacao:`A toxoplasmose é uma das principais causas de aborto em ovinos. A infecção durante a gestação causa aborto, natimortos, mumificação fetal e nascimento de cordeiros fracos. O diagnóstico é por sorologia (ELISA) e histopatologia (necrose focal no cérebro e placenta).`},{id:`cga-041`,banca:`UFMT`,ano:2023,prova:`UFMT — Concurso 2023`,tipo:`concurso`,topico:`clinica_ovina`,subtopico:`Caseous lymphadenitis`,dificuldade:`dificil`,enunciado:`A linfadenite caseosa em ovinos é causada por:`,alternativas:[`Mycobacterium bovis.`,`Corynebacterium pseudotuberculosis, que causa abscessos caseosos nos linfonodos e órgãos internos.`,`Arcanobacterium pyogenes.`,`Rhodococcus equi.`,`Staphylococcus aureus.`],resposta_correta:`B`,explicacao:`A linfadenite caseosa é causada por Corynebacterium pseudotuberculosis, que forma abscessos caseosos em linfonodos superficiais (principalmente submandibular, parotídeo, pré-escapular) e órgãos internos. A bactéria é resistente no ambiente. O diagnóstico é por cultura do pus.`},{id:`cga-042`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Exame clínico caprino`,dificuldade:`basico`,enunciado:`Os parâmetros fisiológicos normais de caprinos adultos são:`,alternativas:[`FC: 70-90 bpm; FR: 15-30 mpm; temperatura: 38,5-40,0°C`,`FC: 40-60 bpm; FR: 10-20 mpm; temperatura: 37,5-39,0°C`,`FC: 60-80 bpm; FR: 20-40 mpm; temperatura: 39,0-40,5°C`,`FC: 80-110 bpm; FR: 15-30 mpm; temperatura: 38,5-40,0°C`,`FC: 50-70 bpm; FR: 10-15 mpm; temperatura: 37,0-38,5°C`],resposta_correta:`A`,explicacao:`Os parâmetros fisiológicos normais de caprinos adultos são: FC 70-90 bpm, FR 15-30 mpm e temperatura retal 38,5-40,0°C. Os valores são semelhantes aos ovinos.`},{id:`cga-043`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Artrite encefalite caprina`,dificuldade:`medio`,enunciado:`A Artrite Encefalite Caprina (CAE) é causada por um lentivírus. Sobre a doença, assinale a alternativa CORRETA:`,alternativas:[`A transmissão ocorre apenas por via venérea.`,`A principal via de transmissão é o colostro/leite infectada, e os sinais incluem artrite crônica progressiva, encefalite em cabritos e pneumonite intersticial.`,`O diagnóstico é feito exclusivamente por hemograma.`,`O tratamento com antivirais é eficaz.`,`A infecção é autolimitada.`],resposta_correta:`B`,explicacao:`A CAE é transmitida principalmente pelo colostro/leite infectada. Os sinais incluem artrite crônica progressiva (forma articular), encefalite em cabritos (forma neurológica), pneumonite intersticial e mastite. O diagnóstico é por ELISA ou AGID. Não há tratamento.`},{id:`cga-044`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Doenças respiratórias caprinas`,dificuldade:`medio`,enunciado:`A pneumonia contagiosa caprina (CCPP) é causada por:`,alternativas:[`Mannheimia haemolytica.`,`Mycoplasma capricolum subsp. capripneumoniae.`,`Pasteurella multocida.`,`Bibersteinia trehalosi.`,`Mycoplasma mycoides subsp. mycoides.`],resposta_correta:`B`,explicacao:`A CCPP (Contagious Caprine Pleuropneumonia) é causada por Mycoplasma capricolum subsp. capripneumoniae. É uma doença de notificação obrigatória à OIE, com alta morbidade e mortalidade. Os sinais incluem febre, dispneia, corrimento nasal e pneumonia fibrinosa.`},{id:`cga-045`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Virose caprina`,dificuldade:`medio`,enunciado:`A Artrite Encefalite Caprina (CAE) e a Leucose Enzoótica Caprina são causadas por lentivírus da família Retroviridae. O diagnóstico de rotina é feito por:`,alternativas:[`PCR em tempo real.`,`ELISA e/ou AGID (teste de Coggins modificado).`,`Cultivo viral em células.`,`Hemograma completo.`,`Raspado de pele.`],resposta_correta:`B`,explicacao:`O diagnóstico de rotina da CAE é feito por ELISA (mais sensível) ou AGID (mais específico). O ELISA detecta anticorpos anti-lentivírus. O teste de Coggins modificado (AGID) é usado como teste confirmatório.`},{id:`cga-046`,banca:`UFMG`,ano:2022,prova:`UFMG — Concurso 2022`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Toxemia da gestação`,dificuldade:`dificil`,enunciado:`A toxemia da gestação (pregnancy toxemia) em caprinos ocorre no terço final da gestação, quando:`,alternativas:[`A demanda energética dos fetos excede a ingestão de energia, levando a cetose e hipoglicemia.`,`Há excesso de proteína na dieta.`,`A cabra ingere plantas hepatotóxicas.`,`O cálcio sérico está elevado.`,`Há infecção uterina.`],resposta_correta:`A`,explicacao:`A toxemia da gestação ocorre quando a demanda energética dos fetos (principalmente em gestação gemelar) excede a capacidade de ingestão e metabolismo energético, levando a hipoglicemia, cetose e mobilização excessiva de gordura. O diagnóstico é por BHBA > 1,2 mmol/L.`},{id:`cga-047`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso 2021`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Agalaxia contagiosa`,dificuldade:`medio`,enunciado:`A agalaxia contagiosa em caprinos é causada por:`,alternativas:[`Staphylococcus aureus.`,`Mycoplasma agalactiae, que causa mastite, artrite e ceratoconjuntivite.`,`Escherichia coli.`,`Corynebacterium pseudotuberculosis.`,`Brucella melitensis.`],resposta_correta:`B`,explicacao:`A agalaxia contagiosa é causada por Mycoplasma agalactiae e afeta cabras e ovelhas. Os sinais incluem mastite aguda (com perda de produção de leite), artrite e ceratoconjuntivite. É uma doença de notificação obrigatória.`},{id:`cga-048`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Enterotoxemia caprina`,dificuldade:`basico`,enunciado:`A enterotoxemia em caprinos por Clostridium perfringens tipo D é prevenida principalmente por:`,alternativas:[`Antibioticoterapia profilática.`,`Vacinação das cabras no terço final da gestação e manejo alimentar adequado.`,`Desparasitação mensal.`,`Suplementação vitamínica.`,`Isolamento dos animais doentes.`],resposta_correta:`B`,explicacao:`A prevenção da enterotoxemia em caprinos baseia-se na vacinação das cabras no terço final da gestação (40 e 20 dias antes do parto) para transferência de imunidade passiva via colostro, e no manejo alimentar adequado (evitar mudanças bruscas na dieta).`},{id:`cga-049`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso 2023`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Maedi-Visna`,dificuldade:`dificil`,enunciado:`O Maedi-Visna é uma lentivirose que afeta ovinos e caprinos. Os sinais clínicos incluem:`,alternativas:[`Diarreia crônica e desnutrição.`,`Pneumonia progressiva (Maedi) e leucoencefalite (Visna), com evolução lenta e inexorável.`,`Artrite aguda com febre alta.`,`Dermatite pruriginosa.`,`Ceratoconjuntivite aguda.`],resposta_correta:`B`,explicacao:`O Maedi-Visna é uma lentivirose de evolução lenta e progressiva. Maedi (dispneia progressiva por pneumonia intersticial) e Visna (leucoencefalite com paralisia progressiva). Não há tratamento. O diagnóstico é por ELISA ou AGID.`},{id:`cga-050`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Agropecuário 2022`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Brucelose caprina`,dificuldade:`medio`,enunciado:`A brucelose em caprinos, causada por Brucella melitensis, é uma zoonose de alta importância. A profilaxia recomendada pelo MAPA inclui:`,alternativas:[`Antibioticoterapia de rebanho.`,`Sorologia e descarte dos animais positivos, sem vacinação.`,`Vacinação com B19 em todos os animais.`,`Quarentena de 30 dias.`,`Tratamento e manutenção dos animais no rebanho.`],resposta_correta:`B`,explicacao:`A profilaxia da brucelose caprina recomendada pelo MAPA inclui o diagnóstico sorológico (RBPT e confirmatório) e o descarte dos animais positivos. Não há vacinação para caprinos no Brasil (a B19 é para bovinos). O rebanho deve ser monitorado periodicamente.`},{id:`cga-051`,banca:`UFBA`,ano:2021,prova:`UFBA — Concurso 2021`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Leptospirose caprina`,dificuldade:`medio`,enunciado:`A leptospirose em caprinos pode causar:`,alternativas:[`Apenas infecção subclínica.`,`Aborto, natimortos, mastite aguda, hemoglobinúria e icterícia.`,`Pneumonia intersticial crônica.`,`Dermatite granulomatosa.`,`Encefalite viral.`],resposta_correta:`B`,explicacao:`A leptospirose em caprinos pode causar aborto no terço final da gestação, natimortos, mastite aguda, hemoglobinúria e icterícia (forma icterohemorrágica). Os principais sorovar são Hardjo, Pomona e Icterohaemorrhagiae.`},{id:`cga-052`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Acidose ruminal caprina`,dificuldade:`medio`,enunciado:`Caprinos em confinamento apresentam diarreia, desidratação, timpanismo e descoordenação motora após ingestão excessiva de concentrado. O diagnóstico mais provável é:`,alternativas:[`Enterotoxemia por Clostridium perfringens.`,`Acidose ruminal aguda por ingestão excessiva de carboidratos fermentescíveis.`,`Pneumonia aspirativa.`,`Intoxicação por plantas.`,`Hipocalcemia.`],resposta_correta:`B`,explicacao:`A acidose ruminal aguda ocorre após ingestão excessiva de concentrado (carboidratos fermentescíveis), levando à produção excessiva de ácido lático no rúmen, queda do pH ruminal (<5,0), endotoxemia e sinais sistêmicos. O diagnóstico é pelo pH ruminal.`},{id:`cga-053`,banca:`UFRPE`,ano:2023,prova:`UFRPE — Concurso 2023`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Prolapso retal caprino`,dificuldade:`basico`,enunciado:`O prolapso retal em caprinos é frequentemente associado a:`,alternativas:[`Excesso de exercício físico.`,`Tenesmo por diarreia crônica, parasitismo intenso ou infecção intestinal.`,`Hipercalcemia.`,`Deficiência de vitamina A.`,`Intoxicação por cobre.`],resposta_correta:`B`,explicacao:`O prolapso retal em caprinos é frequentemente associado a tenesmo por diarreia crônica, parasitismo intenso (verminose), infecções intestinais ou coccidiose. O tratamento inclui redução do prolapso, sutura em bolsa de tabaco e correção da causa subjacente.`},{id:`cga-054`,banca:`UFPR`,ano:2022,prova:`UFPR — Concurso 2022`,tipo:`concurso`,topico:`clinica_caprina`,subtopico:`Dermatite caprina`,dificuldade:`basico`,enunciado:`A dermatite pustular contagiosa em caprinos é causada por:`,alternativas:[`Staphylococcus aureus.`,`Orf virus (Parapoxvirus), causando lesões crostosas nos lábios, narinas e úbere.`,`Dermatophilus congolensis.`,`Trichophyton mentagrophytes.`,`Sarcoptes scabiei.`],resposta_correta:`B`,explicacao:`A ectima contagioso (Orf) é causado por Parapoxvirus e causa lesões crostosas proliferativas nos lábios, narinas, úbere e membros. É zoonótica. O diagnóstico é clínico e confirmado por PCR. Não há tratamento específico; as lesões são autolimitadas em 4-6 semanas.`},{id:`cga-055`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Parâmetros fisiológicos suínos`,dificuldade:`basico`,enunciado:`Os parâmetros fisiológicos normais de suínos adultos são:`,alternativas:[`FC: 60-100 bpm; FR: 8-18 mpm; temperatura: 38,0-39,5°C`,`FC: 70-90 bpm; FR: 10-20 mpm; temperatura: 38,5-40,0°C`,`FC: 80-120 bpm; FR: 15-30 mpm; temperatura: 39,0-40,5°C`,`FC: 40-60 bpm; FR: 8-12 mpm; temperatura: 37,5-39,0°C`,`FC: 100-140 bpm; FR: 20-40 mpm; temperatura: 38,0-39,0°C`],resposta_correta:`A`,explicacao:`Os parâmetros fisiológicos normais de suínos adultos são: FC 60-100 bpm, FR 8-18 mpm e temperatura retal 38,0-39,5°C. A temperatura retal é frequentemente utilizada como indicador de saúde no manejo de granjas.`},{id:`cga-056`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Peste suína africana`,dificuldade:`medio`,enunciado:`Sobre a Peste Suína Africana (PSA), assinale a alternativa CORRETA:`,alternativas:[`É causada por um vírus RNA da família Picornaviridae.`,`É causada por um vírus DNA da família Asfarviridae, transmitida por carrapatos Ornithodoros e contato direto, com mortalidade de até 100% em suínos domésticos.`,`Não afeta javalis (Sus scrofa).`,`Existe vacina comercial eficaz disponível.`,`A transmissão ocorre exclusivamente por via aérea.`],resposta_correta:`B`,explicacao:`A PSA é causada por um vírus DNA (Asfivirus, Asfarviridae), transmitida por carrapatos Ornithodoros, contato direto e fômites. A mortalidade pode chegar a 100%. Não há vacina. Os javalis são reservatórios. É doença de notificação obrigatória à OIE.`},{id:`cga-057`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Síndrome respiratória suína`,dificuldade:`medio`,enunciado:`A Síndrome Respiratória e Reprodutiva dos Suínos (PRRS) é causada por:`,alternativas:[`Circovírus suíno tipo 2 (PCV2).`,`Vírus da PRRS (Arterivirus, família Arteriviridae), que causa distúrbios reprodutivos e respiratórios.`,`Mycoplasma hyopneumoniae.`,`Influenza suína H1N1.`,`Aujeszky's disease virus.`],resposta_correta:`B`,explicacao:`A PRRS é causada por um Arterivirus (família Arteriviridae). Os sinais incluem aborto, natimortos, natimortos mumificados, leitões fracos e doença respiratória em suínos de crescimento. Doença de grande impacto econômico na suinocultura mundial.`},{id:`cga-058`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Doença de Aujeszky`,dificuldade:`medio`,enunciado:`A Doença de Aujeszky (pseudoraiva) em suínos é causada por um herpesvírus (Suid herpesvirus 1). Sobre a doença, é CORRETO:`,alternativas:[`Acomete exclusivamente suínos e não há outros hospedeiros.`,`Em suínos adultos causa sinais respiratórios e reprodutivos; em leitões neonatos causa encefalite com mortalidade alta. É fatal para cães, gatos e bovinos.`,`O diagnóstico é feito exclusivamente por hemograma.`,`O tratamento com antivirais é eficaz.`,`Não há programa de erradicação no Brasil.`],resposta_correta:`B`,explicacao:`A Doença de Aujeszky afeta suínos como hospedeiro natural (reservatório), causando sinais respiratórios e reprodutivos em adultos e encefalite fatal em leitões. É fatal para cães, gatos e bovinos. O diagnóstico é por sorologia (ELISA gB). O Brasil tem programa de erradicação.`},{id:`cga-059`,banca:`UFMG`,ano:2022,prova:`UFMG — Concurso 2022`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Circovirose suína`,dificuldade:`dificil`,enunciado:`A Doença Multissistêmica do Definhamento dos Suínos (PMWS), causada por Circovírus suíno tipo 2 (PCV2), é caracterizada por:`,alternativas:[`Apenas sinais respiratórios.`,`Definhamento progressivo, linfadenomegalia, palidez, icterícia e sinais respiratórios e/ou entéricos em leitões de 5-16 semanas.`,`Morte súbita em suínos adultos.`,`Apenas sinais reprodutivos.`,`Dermatite e descoloração da pele.`],resposta_correta:`B`,explicacao:`A PMWS causada por PCV2 acomete leitões de 5-16 semanas, causando definhamento progressivo, linfadenomegalia, palidez, icterícia, sinais respiratórios e/ou entéricos. A lesão característica é a depleção linfóide. A vacinação é eficaz na prevenção.`},{id:`cga-060`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Erisipela suína`,dificuldade:`basico`,enunciado:`A erisipela suína é causada por:`,alternativas:[`Staphylococcus hyicus.`,`Erysipelothrix rhusiopathiae, causando formas aguda (septicemia), subaguda (urticária) e crônica (artrite e endocardite).`,`Streptococcus suis.`,`Actinobacillus pleuropneumoniae.`,`Haemophilus parasuis.`],resposta_correta:`B`,explicacao:`A erisipela é causada por Erysipelothrix rhusiopathiae. A forma aguda causa septicemia com febre alta e morte súbita. A forma subaguda apresenta lesões de pele em losango (urticária). A forma crônica causa artrite e endocardite. A vacinação é eficaz.`},{id:`cga-061`,banca:`CESPE`,ano:2023,prova:`CESPE — Veterinário 2023`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Rinite atrófica suína`,dificuldade:`medio`,enunciado:`A rinite atrófica progressiva (RAP) em suínos é causada por:`,alternativas:[`Mycoplasma hyopneumoniae.`,`Pasteurella multocida toxigênica (sorotipos A e D) e Bordetella bronchiseptica.`,`Actinobacillus pleuropneumoniae.`,`Streptococcus suis.`,`Influenza suína.`],resposta_correta:`B`,explicacao:`A RAP é causada por Pasteurella multocida toxigênica (produtora de toxina dermonecrótica, sorotipos A e D) e/ou Bordetella bronchiseptica. Os sinais incluem espirros, deformidade do focinho (desvio lateral), atrofia das conchas nasais e perda de produtividade.`},{id:`cga-062`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Agropecuário 2022`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Febre suína clássica`,dificuldade:`medio`,enunciado:`A Febre Suína Clássica (FSC) é causada por um Pestivirus (Flaviviridae). Os sinais clínicos incluem:`,alternativas:[`Apenas sinais respiratórios leves.`,`Febre, prostração, cianose das extremidades, diarreia, vômitos, sinais neurológicos e alta mortalidade em leitões.`,`Dermatite pruriginosa.`,`Artrite crônica.`,`Apenas sinais reprodutivos.`],resposta_correta:`B`,explicacao:`A FSC causa sinais sistêmicos graves: febre, prostração, cianose de orelhas e extremidades, diarreia, vômitos, sinais neurológicos e alta mortalidade. Em gestantes causa aborto e natimortos. O Brasil é livre de FSC desde 2021.`},{id:`cga-063`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Micoespirações suínas`,dificuldade:`dificil`,enunciado:`A pneumonia enzoótica suína é causada por:`,alternativas:[`Actinobacillus pleuropneumoniae.`,`Mycoplasma hyopneumoniae, causando tosse crônica, retardo de crescimento e pneumonia intersticial.`,`Pasteurella multocida.`,`Streptococcus suis.`,`Haemophilus parasuis.`],resposta_correta:`B`,explicacao:`A pneumonia enzoótica suína é causada por Mycoplasma hyopneumoniae, caracterizada por tosse crônica não produtiva, retardo de crescimento e pneumonia intersticial. A infecção facilita a colonização por bactérias secundárias (P. multocida, A. pleuropneumoniae).`},{id:`cga-064`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Pleuropneumonia suína`,dificuldade:`medio`,enunciado:`A pleuropneumonia contagiosa suína é causada por:`,alternativas:[`Mycoplasma hyopneumoniae.`,`Actinobacillus pleuropneumoniae (APP), que causa pneumonia fibrinohemorrágica necrosante e pleurite.`,`Pasteurella multocida.`,`Bordetella bronchiseptica.`,`Streptococcus suis.`],resposta_correta:`B`,explicacao:`A pleuropneumonia contagiosa é causada por Actinobacillus pleuropneumoniae, que causa pneumonia fibrinohemorrágica necrosante, pleurite e alta mortalidade na forma aguda. Existem 18 biotipos sorológicos. O diagnóstico é por cultura e PCR.`},{id:`cga-065`,banca:`UFRGS`,ano:2023,prova:`UFRGS — Concurso 2023`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Diarreia neonatal suína`,dificuldade:`basico`,enunciado:`A diarreia neonatal em leitões nas primeiras 48 horas de vida é mais frequentemente causada por:`,alternativas:[`Salmonella spp.`,`Escherichia coli enterotoxigênica (ETEC).`,`Clostridium perfringens tipo C.`,`Rotavírus.`,`Coccidioses (Isospora suis).`],resposta_correta:`B`,explicacao:`A E. coli enterotoxigênica (ETEC) é a principal causa de diarreia neonatal em leitões nas primeiras 48 horas de vida, produzindo enterotoxinas termoestáveis (STa, STb) e termolábeis (LT). A vacinação das porcas e o manejo do colostro são essenciais.`},{id:`cga-066`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso 2022`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Síndrome do desmame suíno`,dificuldade:`medio`,enunciado:`A Síndrome Multissistêmica do Definhamento Pós-Desmame (PMWS) é associada a qual agente?`,alternativas:[`PRRS virus.`,`Circovírus suíno tipo 2 (PCV2).`,`Mycoplasma hyopneumoniae.`,`Influenza suína.`,`Salmonella choleraesuis.`],resposta_correta:`B`,explicacao:`A PMWS (Doença Multissistêmica do Definhamento) é causada por PCV2, afetando leitões desmamados (5-16 semanas). Os sinais incluem definhamento, linfadenomegalia, palidez e sinais respiratórios. A vacinação é altamente eficaz.`},{id:`cga-067`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso 2021`,tipo:`concurso`,topico:`clinica_suina`,subtopico:`Estreptococose suína`,dificuldade:`medio`,enunciado:`A meningite em leitões causada por Streptococcus suis apresenta:`,alternativas:[`Apenas sinais respiratórios.`,`Febre, rigidez de nuca, convulsões, opistótonos e alta mortalidade em leitões de 3-8 semanas.`,`Diarreia aquosa profusa.`,`Dermatite hemorrágica.`,`Artrite crônica em suínos adultos.`],resposta_correta:`B`,explicacao:`Streptococcus suis é a principal causa de meningite bacteriana em leitões de 3-8 semanas de vida. Os sinais incluem febre, rigidez de nuca, convulsões, opistótonos, desvio lateral de cabeça e artrite. É zoonótica em trabalhadores de granjas.`},{id:`cga-068`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Timpanismo ruminal`,dificuldade:`medio`,enunciado:`No tratamento do timpanismo gasoso primário em bovinos, a primeira conduta é:`,alternativas:[`Administração de óleo mineral via oral.`,`Trocariz ruminal (rumenocentese) no flanco esquerdo, fossa paralombar, para descompressão imediata.`,`Passagem de sonda ororuminal.`,`Administração de antibióticos.`,`Cirurgia de rumenotomia.`],resposta_correta:`B`,explicacao:`No timpanismo gasoso agudo com desconforto respiratório intenso, a trocariz ruminal (rumenocentese) no flanco esquerdo é a primeira conduta para descompressão imediata e salvamento do animal. A sonda ororuminal é tentada em seguida.`},{id:`cga-069`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Cólica equina grave`,dificuldade:`dificil`,enunciado:`Um equino com cólica intensa que não responde ao tratamento clínico com analgésicos (flunixin meglumine 1,1 mg/kg IV) apresenta taquicardia (80 bpm), refluxo nasogástrico fecaloide e distensão intestinal à palpação retal. A conduta mais indicada é:`,alternativas:[`Repetir a dose de analgésico.`,`Indicar eutanásia imediatamente.`,`Encaminhar para laparotomia exploratória (intervenção cirúrgica).`,`Apenas fluidoterapia e observação.`,`Administrar antibióticos e aguardar.`],resposta_correta:`C`,explicacao:`Taquicardia persistente, refluxo nasogástrico fecaloide e distensão intestinal são indicativos de obstrução intestinal grave que requer intervenção cirúrgica. A resposta insuficiente aos analgésicos indica lesão irreversível. A laparotomia exploratória é urgente.`},{id:`cga-070`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Distocia em bovinos`,dificuldade:`medio`,enunciado:`Na distocia em bovinos, a apresentação fetal mais comum que requer intervenção é:`,alternativas:[`Apresentação pélvica (posterior).`,`Desvio lateral de cabeça, flexão de cotovelo ou apresentação ventral de um membro anterior.`,`Herniação do intestino através do útero rasgado.`,`Gêmeos simultaneamente no canal do parto.`,`Torsão uterina.`],resposta_correta:`B`,explicacao:`As causas mais comuns de distocia em bovinos são desvios de posição e apresentação fetal: desvio lateral de cabeça, flexão de cotovelo, apresentação ventral de um membro anterior. A correção é por repasse fetal sob anestesia epidural.`},{id:`cga-071`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Prolapso uterino bovino`,dificuldade:`dificil`,enunciado:`No tratamento do prolapso uterino em bovinos, a conduta CORRETA é:`,alternativas:[`Redução imediata sem anestesia.`,`Redução sob anestesia epidural, com o animal em posição esternal, elevação dos membros pélvicos, lavagem com solução antisséptica e antibioticoterapia.`,`Apenas antibioticoterapia.`,`Amanhamento cirúrgico imediato (histerectomia).`,`Aguardar expulsão espontânea.`],resposta_correta:`B`,explicacao:`O tratamento do prolapso uterino inclui: anestesia epidural, elevação dos membros pélvicos, lavagem do útero com solução antisséptica morna, redução cuidadosa, sutura vulvar (zafirah) e antibioticoterapia. O prolapso é uma emergência.`},{id:`cga-072`,banca:`UFMG`,ano:2022,prova:`UFMG — Residência 2022`,tipo:`residencia`,topico:`emergencias_ga`,subtopico:`Choque hipovolêmico equino`,dificuldade:`dificil`,enunciado:`No tratamento do choque hipovolêmico em equinos, a fluidoterapia de escolha inicial é:`,alternativas:[`Soro fisiológico 0,9% em bolus de 50 mL/kg.`,`Ringer com Lactato em bolus de 20-40 mL/kg, repetido conforme resposta clínica (FC, TRC, pulso).`,`Soro glicosado 5% em infusão contínua.`,`Plasma autólogo.`,`Água destilada via oral.`],resposta_correta:`B`,explicacao:`No choque hipovolêmico equino, a fluidoterapia inicial é com Ringer com Lactato em bolus de 20-40 mL/kg, repetido conforme a resposta clínica. A monitoração inclui FC, TRC, pulso, pressão arterial e lactato sérico.`},{id:`cga-073`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso 2021`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Hemorragia em grandes animais`,dificuldade:`basico`,enunciado:`No controle de hemorragia arterial em grandes animais, a primeira conduta é:`,alternativas:[`Administrar vitamina K.`,`Compressão digital ou torniquete proximal ao sítio de sangramento e fluidoterapia.`,`Transfusão sanguínea imediata.`,`Aguardar formação do trombo.`,`Administrar ácido tranexâmico.`],resposta_correta:`B`,explicacao:`No controle de hemorragia arterial, a primeira conduta é a compressão digital ou aplicação de torniquete proximal ao sítio de sangramento, seguida de fluidoterapia para reposição volêmica. A hemostasia cirúrgica definitiva é realizada em seguida.`},{id:`cga-074`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Mioglobinúria equina`,dificuldade:`medio`,enunciado:`A mioglobinúria paralítica (rabdomiólise) em equinos é uma emergência que requer:`,alternativas:[`Apenas repouso e hidratação oral.`,`Fluidoterapia agressiva para prevenir insuficiência renal aguda, analgesia e anti-inflamatórios.`,`Cirurgia imediata.`,`Antibioticoterapia de amplo espectro.`,`Exercício controlado para prevenir atrofia muscular.`],resposta_correta:`B`,explicacao:`A rabdomiólise equina é uma emergência devido ao risco de insuficiência renal aguda por obstrução dos túbulos renais por mioglobina. O tratamento inclui fluidoterapia agressiva (para manter diurese >1 mL/kg/h), analgesia e anti-inflamatórios.`},{id:`cga-075`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário 2023`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Timpanismo espumoso`,dificuldade:`basico`,enunciado:`No tratamento do timpanismo espumoso em bovinos, o agente antiespumante de primeira escolha é:`,alternativas:[`Penicilina intraruminal.`,`Poloxaleno, dimeticona ou óleo mineral (500-1000 mL via sonda ororuminal).`,`Cloreto de sódio hipertônico.`,`Bicarbonato de sódio.`,`Ácido acético diluído.`],resposta_correta:`B`,explicacao:`O tratamento do timpanismo espumoso é com agentes antiespumantes: poloxaleno, dimeticona ou óleo mineral (500-1000 mL), administrados via sonda ororuminal. A trocariz é indicada para timpanismo gasoso.`},{id:`cga-076`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Concurso 2022`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Vólvulo gástrico equino`,dificuldade:`dificil`,enunciado:`O vólvulo gástrico em equinos é uma emergência cirúrgica caracterizada por:`,alternativas:[`Dor leve e intermitente, sem sinais sistêmicos.`,`Dor intensa e persistente, grande volume de refluxo nasogástrico, taquicardia e choque.`,`Diarréia profusa e desidratação.`,`Tosse e dispneia.`,`Edema de membros e dermatite.`],resposta_correta:`B`,explicacao:`O vólvulo gástrico em equinos causa dor intensa, grande volume de refluxo nasogástrico, taquicardia e choque. É uma emergência cirúrgica que requer descompressão gástrica imediata (sonda nasogástrica) e cirurgia de emergência.`},{id:`cga-077`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal Agropecuário 2023`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Cesariana bovina`,dificuldade:`medio`,enunciado:`A cesariana em bovinos é indicada quando:`,alternativas:[`O feto está vivo e apresentação é normal.`,`Há impossibilidade de resolução por via vaginal (feto muito grande, incompatibilidade feto-pélvica, torção uterina não resolvida, malformações fetais).`,`A vaca apresenta apenas contrações fracas sem obstrução.`,`O parto está em fase de dilatação e progride normalmente.`,`Há apenas retenção de placenta.`],resposta_correta:`B`,explicacao:`A cesariana é indicada quando não é possível resolver a distócia por via vaginal: incompatibilidade feto-pélvica, torção uterina não resolvida por rolling, malformações fetais ou quando o feto já morreu e é necessário um procedimento fetal.`},{id:`cga-078`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Concurso 2022`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Fraturas em equinos`,dificuldade:`medio`,enunciado:`Fraturas abertas de terço distal do metatarso em equinos de esporte:`,alternativas:[`Sempre têm bom prognóstico com tratamento conservador.`,`O prognóstico é reservado a desfavorável devido ao risco de infecção, osteomielite e laminita no membro contralateral.`,`Devem ser tratadas apenas com imobilização gessada.`,`São sempre indicação de eutanásia.`,`Respondem bem ao tratamento com antibióticos isoladamente.`],resposta_correta:`B`,explicacao:`Fraturas abertas em equinos têm prognóstico reservado a desfavorável devido ao risco de infecção óssea (osteomielite), consolidação deficiente e laminita compensatória no membro contralateral pelo apoio excessivo.`},{id:`cga-079`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Torção uterina`,dificuldade:`medio`,enunciado:`A torção uterina em bovinos é corrigida por:`,alternativas:[`Administração de ocitocina.`,`Rolling da vaca (rotação do animal) na direção oposta à torção, com animal em decúbito.`,`Cesariana imediata em todos os casos.`,`Apenas massagem uterina retal.`,`Administração de anti-inflamatórios.`],resposta_correta:`B`,explicacao:`A torção uterina em bovinos é corrigida pelo método de rolling (rotação do animal em decúbito na direção oposta à torção). A torção de 180-360° no sentido horário é corrigida rolando o animal para o lado esquerdo. Casos refratários requerem cesariana.`},{id:`cga-080`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Concurso 2022`,tipo:`concurso`,topico:`emergencias_ga`,subtopico:`Prolapso vaginal`,dificuldade:`basico`,enunciado:`O prolapso vaginal em vacas gestantes é tratado por:`,alternativas:[`Cirurgia corretiva imediata.`,`Sutura vulvar em "zafirah" (sutura de Bühner) e manutenção até o parto.`,`Redução manual e antibioticoterapia.`,`Indução do parto.`,`Descarte do animal.`],resposta_correta:`B`,explicacao:`O prolapso vaginal em vacas gestantes é tratado com sutura vulvar em "zafirah" (sutura de Bühner), que mantém os lábios vulvares aproximados até o parto. A sutura é removida quando o parto se inicia. É comum em vacas com hipocalcemia.`},{id:`cga-081`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Brucelose bovina`,dificuldade:`medio`,enunciado:`Sobre a brucelose bovina, causada por Brucella abortus, assinale a alternativa CORRETA:`,alternativas:[`A transmissão ocorre apenas por via venérea.`,`O diagnóstico de triagem é feito por antígeno acidificado tamponado (AAT/RBPT) e confirmado por 2-mercaptoetanol ou ELISA.`,`O tratamento com estreptomicina é eficaz.`,`A vacinação com B19 elimina a infecção do rebanho.`,`Não é zoonose.`],resposta_correta:`B`,explicacao:`A brucelose bovina é diagnosticada por triagem com AAT (antígeno acidificado tamponado) ou RBPT, e confirmada por 2-mercaptoetanol ou ELISA. A transmissão é por contato com material abortivo, leite e sêmen. É zoonose importante. A profilaxia inclui vacinação com B19 e RB51.`},{id:`cga-082`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Tuberculose bovina`,dificuldade:`medio`,enunciado:`O diagnóstico da tuberculose bovina, causada por Mycobacterium bovis, é feito por:`,alternativas:[`Hemograma completo.`,`Intradermotuberculinização com tuberculina PPD bovina (teste cervical comparativo ou teste cervical simples).`,`Sorologia (ELISA).`,`Cultivo em meio Sabouraud.`,`PCR em sangue periférico.`],resposta_correta:`B`,explicacao:`O diagnóstico da tuberculose bovina é feito pela intradermotuberculinização com PPD bovina. O teste cervical comparativo (TCC) usa PPD bovina e aviária para diferenciar infecções. Animais reatores são descartados. O cultivo em meio Löwenstein-Jensen é o padrão-ouro.`},{id:`cga-083`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Leptospirose bovina`,dificuldade:`medio`,enunciado:`A leptospirose em bovinos é causada por Leptospira spp. Os sinais clínicos mais comuns são:`,alternativas:[`Pneumonia e tosse crônica.`,`Aborto no terço final da gestação, natimortos, hemoglobinúria, icterícia e queda de produção de leite.`,`Diarreia crônica e perda de peso.`,`Artrite e claudicação.`,`Dermatite e prurido.`],resposta_correta:`B`,explicacao:`A leptospirose em bovinos causa aborto no terço final, natimortos, hemoglobinúria, icterícia e queda de produção leiteira. O sorovar Hardjo-bovis é o mais frequente em bovinos. O diagnóstico é por MAT (soroaglutinação microscópica).`},{id:`cga-084`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Agropecuário 2022`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Carbúnculo sintomático`,dificuldade:`basico`,enunciado:`O carbúnculo sintomático (quartelo) em bovinos é causado por:`,alternativas:[`Clostridium tetani.`,`Clostridium chauvoei, que causa mionecrose enfisematosa com crepitação ao palpar.`,`Clostridium perfringens tipo D.`,`Bacillus anthracis.`,`Clostridium septicum.`],resposta_correta:`B`,explicacao:`O carbúnculo sintomático é causado por Clostridium chauvoei, que causa mionecrose enfisematosa nos músculos esqueléticos. O animal apresenta claudicação, tumefação crepitante nos músculos afetados e morte súbita. A vacinação é preventiva.`},{id:`cga-085`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`IBR/BHV-1`,dificuldade:`medio`,enunciado:`A Rinotraqueíte Infecciosa Bovina (IBR), causada por Bovine Herpesvirus 1 (BHV-1), pode manifestar-se nas formas:`,alternativas:[`Apenas respiratória.`,`Respiratória (rinotraqueíte), genital (vulvovaginite/balanopostite), ocular e sistêmica (em bezerros).`,`Apenas reprodututiva.`,`Apenas neurológica.`,`Apenas cutânea.`],resposta_correta:`B`,explicacao:`O BHV-1 causa múltiplas manifestações clínicas: respiratória (rinotraqueíte infecciosa), genital (vulvovaginite pustular infecciosa, balanopostite), ocular (ceratoconjuntivite) e sistêmica (viremia em bezerros). O vírus causa latência no gânglio trigêmeo.`},{id:`cga-086`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Raiva em grandes animais`,dificuldade:`basico`,enunciado:`A raiva é uma zoonose viral letal. Em bovinos e equinos, a forma clínica predominante é:`,alternativas:[`Furiosa (agressividade intensa).`,`Paralítica (muda), com dificuldade de locomoção, prolapso do terceiro pálpebra e evolução para decúbito.`,`Subclínica, com eliminação viral pela saliva.`,`Cutânea, com lesões dermatológicas.`,`Gastrointestinal, com diarreia.`],resposta_correta:`B`,explicacao:`Em bovinos e equinos, a raiva apresenta-se predominantemente na forma paralítica (muda), com dificuldade de locomoção, ataxia, prolapso do terceiro pálpebra, sialorreia e evolução para decúbito em 3-5 dias.`},{id:`cga-087`,banca:`UNESP`,ano:2022,prova:`UNESP — Concurso 2022`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`BVD/MD`,dificuldade:`dificil`,enunciado:`A Diarreia Viral Bovina (BVD), causada por Pestivirus (BVDV), é importante porque:`,alternativas:[`Afeta apenas bezerros adultos.`,`Fêmeas infectadas entre 40-120 dias de gestação geram bezerros persistentemente infectados (PI), que eliminam o vírus por toda a vida.`,`O diagnóstico é feito exclusivamente por hemograma.`,`Existe tratamento antiviral eficaz.`,`A vacinação elimina o vírus do rebanho.`],resposta_correta:`B`,explicacao:`A infecção pelo BVDV entre 40-120 dias de gestação (quando o feto é imunologicamente tolerante) gera bezerros persistentemente infectados (PI), que eliminam grandes quantidades de vírus por toda a vida e são a principal fonte de infecção do rebanho.`},{id:`cga-088`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário 2023`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Dermatite nodular contagiosa`,dificuldade:`medio`,enunciado:`A Dermatite Nodular Contagiosa (Lumpy Skin Disease) em bovinos é causada por:`,alternativas:[`Bovine Herpesvirus 2.`,`Lumpy Skin Disease Virus (Capripoxvirus, família Poxviridae).`,`Parapoxvirus.`,`Pseudocowpox virus.`,`Bovine Papular Stomatitis virus.`],resposta_correta:`B`,explicacao:`A Dermatite Nodular Contagiosa (LSD) é causada por um Capripoxvirus (Poxviridae). Causa nódulos cutâneos, febre, linfadenomegalia e queda de produção. É transmitida por insetos e contato direto. É doença de notificação obrigatória à OIE.`},{id:`cga-089`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Anaplasmose bovina`,dificuldade:`medio`,enunciado:`A anaplasmose bovina é causada por Anaplasma marginale, transmitida por carrapatos (Rhipicephalus microplus). Os sinais clínicos incluem:`,alternativas:[`Diarreia e desidratação.`,`Febre, anemia hemolítica, icterícia, taquicardia e hemoglobinúria.`,`Tosse e dispneia.`,`Artrite e edema articular.`,`Dermatite e prurido.`],resposta_correta:`B`,explicacao:`A anaplasmose causa destruição de eritrócitos (hemólise extravascular), levando a febre, anemia progressiva, icterícia, taquicardia e hemoglobinúria (em casos graves). O diagnóstico é por esfregaço de sangue (corpo de inclusão em eritrócitos) e PCR.`},{id:`cga-090`,banca:`UFMT`,ano:2023,prova:`UFMT — Concurso 2023`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Piroplasmose equina`,dificuldade:`medio`,enunciado:`A piroplasmose equina, causada por Babesia caballi e Theileria equi, é transmitida por:`,alternativas:[`Mosquitos Culex.`,`Carrapatos dos gêneros Dermacentor, Rhipicephalus e Amblyomma.`,`Moscas estáveis (Stomoxys calcitrans).`,`Flebotomíneos.`,`Carrapatos Ixodes.`],resposta_correta:`B`,explicacao:`A piroplasmose equina é transmitida por carrapatos dos gêneros Dermacentor, Rhipicephalus e Amblyomma. B. caballi é transmitida transovarianamente pelo carrapato, enquanto T. equi é transmitida transstadialmente.`},{id:`cga-091`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso 2022`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Enterotoxemia`,dificuldade:`basico`,enunciado:`A enterotoxemia por Clostridium perfringens em bovinos, ovinos e caprinos é prevenida por:`,alternativas:[`Antibioticoterapia profilática.`,`Vacinação polivalente clostridial e manejo alimentar adequado.`,`Desparasitação mensal.`,`Suplementação vitamínica.`,`Isolamento dos animais doentes.`],resposta_correta:`B`,explicacao:`A prevenção da enterotoxemia baseia-se na vacinação polivalente clostridial (com reforço anual) e no manejo alimentar adequado (evitar mudanças bruscas na dieta e excesso de concentrado).`},{id:`cga-092`,banca:`UFRGS`,ano:2021,prova:`UFRGS — Concurso 2021`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Salmonelose em grandes animais`,dificuldade:`medio`,enunciado:`A salmonelose em bovinos adultos pode causar:`,alternativas:[`Apenas diarreia branda autolimitada.`,`Enterite aguda com diarreia mucohemorrágica, febre, desidratação, aborto e septicemia.`,`Apenas sinais respiratórios.`,`Dermatite e prurido.`,`Artrite crônica.`],resposta_correta:`B`,explicacao:`A salmonelose em bovinos adultos (causada por S. Dublin, S. Typhimurium) pode causar enterite aguda com diarreia mucohemorrágica, febre, desidratação, aborto e septicemia. A mortalidade pode ser alta. É zoonose.`},{id:`cga-093`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Mastite contagiosa`,dificuldade:`basico`,enunciado:`Os principais agentes contagiosos da mastite bovina são:`,alternativas:[`E. coli e Klebsiella spp.`,`Staphylococcus aureus, Streptococcus agalactiae e Mycoplasma bovis.`,`Pasteurella multocida e Mannheimia haemolytica.`,`Corynebacterium bovis e Streptococcus uberis.`,`Pseudomonas aeruginosa e Nocardia spp.`],resposta_correta:`B`,explicacao:`Os principais agentes contagiosos da mastite são S. aureus, S. agalactiae e M. bovis. A transmissão ocorre durante a ordenha. O controle inclui pré-dipping, pós-dipping, tratamento de vaca seca e descarte de vacas crônicas.`},{id:`cga-094`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`doencas_infecciosas_ga`,subtopico:`Campylobacteriose`,dificuldade:`medio`,enunciado:`A campylobacteriose genital em bovinos, causada por Campylobacter fetus subsp. venerealis, causa:`,alternativas:[`Pneumonia e tosse.`,`Infertilidade, repetição de cio, endometrite e aborto precoce.`,`Diarreia crônica.`,`Dermatite e prurido.`,`Artrite e claudicação.`],resposta_correta:`B`,explicacao:`A campylobacteriose genital bovina causa infertilidade, repetição de cio, endometrite e aborto precoce. A transmissão é venérea. O diagnóstico é por cultura de lavado prepucial/vaginal. A vacinação dos touros e uso de inseminação artificial são preventivos.`},{id:`cga-095`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Hipocalcemia pós-parto`,dificuldade:`basico`,enunciado:`A hipocalcemia pós-parto (febre do leite) em vacas de alta produção ocorre porque:`,alternativas:[`Há excesso de cálcio na dieta.`,`A demanda de cálcio para síntese de colostro excede a capacidade de mobilização óssea e absorção intestinal de cálcio.`,`O animal ingere plantas oxalogênicas.`,`Há insuficiência renal aguda.`,`O paratireoide está hiperativo.`],resposta_correta:`B`,explicacao:`A hipocalcemia pós-parto ocorre quando a demanda de cálcio para produção de colostro excede a capacidade de mobilização óssea e absorção intestinal. Vacas de alta produção e raças leiteiras (Jersey) são mais susceptíveis. O tratamento é com cálcio IV e SC.`},{id:`cga-096`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Hipomagnesemia`,dificuldade:`medio`,enunciado:`A hipomagnesemia (tetania dos pastagens) em bovinos é caracterizada por:`,alternativas:[`Diarreia profusa e desidratação.`,`Hiperexcitabilidade, tremores musculares, convulsões, opistótonos e morte súbita.`,`Tosse e dispneia.`,`Edema submandibular.`,`Icterícia e hemoglobinúria.`],resposta_correta:`B`,explicacao:`A hipomagnesemia ocorre em bovinos em pastejo rápido (primavera) com baixo teor de magnésio na forragem. Os sinais incluem hiperexcitabilidade, tremores, convulsões, opistótonos e morte súbita. O tratamento é com MgSO4 IV lento + Ca gluconato.`},{id:`cga-097`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Acidose ruminal`,dificuldade:`medio`,enunciado:`A acidose ruminal aguda em bovinos é causada por:`,alternativas:[`Ingestão excessiva de forragem de alta qualidade.`,`Ingestão excessiva de concentrados (carboidratos fermentescíveis), levando à produção excessiva de ácido lático no rúmen.`,`Deficiência de cobalto na dieta.`,`Intoxicação por plantas hepatotóxicas.`,`Infecção por Clostridium perfringens.`],resposta_correta:`B`,explicacao:`A acidose ruminal aguda ocorre pela ingestão excessiva de concentrados, que são fermentados rapidamente no rúmen, produzindo ácidos orgânicos e ácido lático em excesso, reduzindo o pH ruminal abaixo de 5,0. Os sinais incluem timpanismo, diarreia e descoordenação.`},{id:`cga-098`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Deslocamento de abomaso`,dificuldade:`medio`,enunciado:`Os fatores predisponentes do deslocamento de abomaso (DAE) em vacas leiteiras incluem:`,alternativas:[`Exercício excessivo.`,`Cetose, hipocalcemia, retenção de placenta, metrite e dietas com alta proporção de concentrado.`,`Infecção por Mycoplasma bovis.`,`Vermifugação excessiva.`,`Suplementação mineral inadequada.`],resposta_correta:`B`,explicacao:`O DAE está associado a doenças do periparto: cetose, hipocalcemia, retenção de placenta, metrite e endometrite (doenças de vaca-cola). Dietas com alta proporção de concentrado e baixa fibra efetiva também são fatores predisponentes.`},{id:`cga-099`,banca:`UFMG`,ano:2022,prova:`UFMG — Residência 2022`,tipo:`residencia`,topico:`doencas_metabolicas_ga`,subtopico:`Cetose bovina`,dificuldade:`dificil`,enunciado:`A cetose subclínica em vacas leiteiras afeta a produtividade e a reprodução. O efeito na reprodução é:`,alternativas:[`Não afeta a reprodução.`,`Reduz a fertilidade por comprometer a função luteal, aumentar a mortalidade embrionária e atrasar o retorno ao cio.`,`Aumenta a taxa de concepção.`,`Causa gestação gemelar.`,`Não há evidência científica.`],resposta_correta:`B`,explicacao:`A cetose subclínica compromete a função luteal (menor produção de progesterona), aumenta a mortalidade embrionária, atrasa o retorno ao cio e reduz a taxa de concepção. Vacas com cetose subclínica têm 3x mais chance de serem descartadas por infertilidade.`},{id:`cga-100`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Metahemoglobinemia`,dificuldade:`medio`,enunciado:`A metahemoglobinemia em bovinos pode ser causada por:`,alternativas:[`Ingestão de nitratos em plantas ou água contaminada.`,`Exercício excessivo.`,`Deficiência de vitamina E.`,`Infecção por Clostridium chauvoei.`,`Ingestão excessiva de sal.`],resposta_correta:`A`,explicacao:`A metahemoglobinemia ocorre pela ingestão de nitratos (forragens adubadas excessivamente, água contaminada). Os nitratos são reduzidos a nitritos no rúmen, que oxidam a hemoglobina a metahemoglobina. Os sinais incluem cianose, dispneia e morte.`},{id:`cga-101`,banca:`CESPE`,ano:2023,prova:`CESPE — Veterinário 2023`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Gordura no fígado`,dificuldade:`dificil`,enunciado:`A esteatose hepática (fígado gorduroso) em vacas de alta produção no pós-parto é:`,alternativas:[`Uma condição benigna sem consequências clínicas.`,`Uma consequência da mobilização excessiva de gordura corporal durante o balanço energético negativo, que compromete a função hepática e a resposta imune.`,`Causada por ingestão de hepatotoxinas.`,`Uma condição infecciosa.`,`Tratável com antibioticoterapia.`],resposta_correta:`B`,explicacao:`A esteatose hepática é resultado da mobilização excessiva de gordura corporal (balanço energético negativo) no pós-parto. Os ácidos graxos não oxidados completamente se acumulam no fígado como triglicerídeos, comprometendo a função hepática, a resposta imune e a reprodução.`},{id:`cga-102`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário 2020`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Hipocalcemia em equinos`,dificuldade:`basico`,enunciado:`A hipocalcemia (síndrome da lactação) em éguas ocorre:`,alternativas:[`Durante a gestação.`,`No pós-parto imediato, associada à produção de colostro, causando tremores musculares, tetania e prolapso retal.`,`Em potros neonatos.`,`Em cavalos de esporte durante exercício intenso.`,`Em equinos idosos com insuficiência renal.`],resposta_correta:`B`,explicacao:`A hipocalcemia em éguas ocorre no pós-parto imediato, associada à alta demanda de cálcio para produção de colostro. Os sinais incluem tremores musculares, tetania, prolapso retal, sudorese e dificuldade de locomoção.`},{id:`cga-103`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Osteodistrofia fibrosa`,dificuldade:`medio`,enunciado:`A osteodistrofia fibrosa nutricional em equinos é causada por:`,alternativas:[`Exercício excessivo.`,`Excesso de fósforo na dieta (Ca:P < 1:1), levando a hiperparatireoidismo secundário nutricional.`,`Deficiência de vitamina A.`,`Infecção por Corynebacterium pseudotuberculosis.`,`Intoxicação por fluoretos.`],resposta_correta:`B`,explicacao:`A osteodistrofia fibrosa ocorre quando a relação Ca:P está invertida (< 1:1), causando hiperparatireoidismo secundário nutricional. Os sinais incluem inchaço facial, claudicação e deformidades ósseas. Equinos alimentados com farelo de trigo (alto P) são mais susceptíveis.`},{id:`cga-104`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Síndrome do downer cow`,dificuldade:`dificil`,enunciado:`A síndrome da vaca caída (downer cow) é:`,alternativas:[`Uma doença infecciosa.`,`Uma condição em que a vaca permanece em decúbito após o tratamento da hipocalcemia, podendo ter miopatia, neuropatia ou fratura.`,`Causada exclusivamente por hipocalcemia.`,`Tratável apenas com eutanásia.`,`Uma condição exclusiva de vacas de corte.`],resposta_correta:`B`,explicacao:`A síndrome da downer cow ocorre quando a vaca não se levanta após tratamento da hipocalcemia. As causas incluem miopatia isquêmica (compressão dos nervos e músculos), neuropatia (paralisia do nervo fibular/fratura de quadril). O tratamento inclui conforto, fluidoterapia e recuperação gradual.`},{id:`cga-105`,banca:`UFMT`,ano:2022,prova:`UFMT — Concurso 2022`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Intoxicação por sal`,dificuldade:`medio`,enunciado:`A intoxicação por sal (cloreto de sódio) em bovinos e equinos pode causar:`,alternativas:[`Apenas diarreia.`,`Sinais neurológicos (convulsões, cegueira, desvio de cabeça), edema cerebral e morte.`,`Apenas desidratação.`,`Hepatotoxicidade.`,`Nefrotoxicidade isolada.`],resposta_correta:`B`,explicacao:`A intoxicação por sal causa sinais neurológicos graves: convulsões, cegueira, desvio de cabeça, tremores e edema cerebral. Ocorre por acesso excessivo ao sal seguido de restrição hídrica ou ingestão de água salgada. O tratamento é com fluidoterapia hipotônica.`},{id:`cga-106`,banca:`UFRPE`,ano:2023,prova:`UFRPE — Concurso 2023`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Deficiência de selênio`,dificuldade:`basico`,enunciado:`A deficiência de selênio em bovinos e equinos causa:`,alternativas:[`Apenas perda de peso.`,`Doença do músculo branco (miopatia branca), cardiomiopatia e retenção de placenta.`,`Dermatite e prurido.`,`Diarreia crônica.`,`Tosse e dispneia.`],resposta_correta:`B`,explicacao:`A deficiência de selênio (associada a vitamina E) causa doença do músculo branco (miodegeneração), cardiomiopatia, retenção de placenta e redução da fertilidade. Em bezerros causa miopatia esquelética e cardíaca.`},{id:`cga-107`,banca:`UFBA`,ano:2021,prova:`UFBA — Concurso 2021`,tipo:`concurso`,topico:`doencas_metabolicas_ga`,subtopico:`Encefalomalácia`,dificuldade:`dificil`,enunciado:`A deficiência de vitamina E em equinos pode causar:`,alternativas:[`Apenas perda de apetite.`,`Encefalomalácia (degeneração do SNC), miopatia esquelética e anemia hemolítica.`,`Dermatite e prurido.`,`Artrite crônica.`,`Diarreia e desidratação.`],resposta_correta:`B`,explicacao:`A deficiência de vitamina E em equinos pode causar encefalomalácia (degeneração do SNC com sinais neurológicos), miopatia esquelética (doença do músculo branco) e anemia hemolítica. É comum em equinos sem acesso a pastagem verde.`},{id:`cga-108`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Haemonchose bovina`,dificuldade:`medio`,enunciado:`Haemonchus placei é o principal nematódeo hematófago de bovinos. Os sinais clínicos incluem:`,alternativas:[`Diarreia profusa e desidratação.`,`Anemia progressiva, hipoproteinemia, edema submandibular (bottle jaw) e perda de peso.`,`Tosse e dispneia.`,`Dermatite e prurido.`,`Artrite e claudicação.`],resposta_correta:`B`,explicacao:`H. placei é um nematódeo hematófago que causa anemia, hipoproteinemia, edema submandibular e perda de peso. O diagnóstico é por EPG (ovos por grama de fezes) e FAMACHA. A resistência aos anti-helmínticos é crescente.`},{id:`cga-109`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Fasciolose`,dificuldade:`medio`,enunciado:`A fasciolose em bovinos e ovinos é causada por Fasciola hepatica. Os sinais clínicos incluem:`,alternativas:[`Apenas diarreia.`,`Perda de peso progressiva, anemia, hipoproteinemia, edema submandibular e hepatomegalia.`,`Tosse e dispneia.`,`Dermatite e prurido.`,`Artrite e claudicação.`],resposta_correta:`B`,explicacao:`A fasciolose causa perda de peso, anemia, hipoproteinemia, edema submandibular e hepatomegalia. Nas formas crônicas, há fibrose hepática. O diagnóstico é por EPG e ELISA. Os caramujos do gênero Lymnaea são hospedeiros intermediários.`},{id:`cga-110`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Verminose equina`,dificuldade:`basico`,enunciado:`Os principais nematódeos gastrintestinais de equinos adultos são:`,alternativas:[`Ascaris suum e Trichuris suis.`,`Cyathostominae (small strongyles), Strongylus vulgaris e Triodontophorus spp.`,`Haemonchus contortus e Trichostrongylus colubriformis.`,`Ostertagia ostertagi e Cooperia spp.`,`Toxocara canis e Ancylostoma caninum.`],resposta_correta:`B`,explicacao:`Os principais nematódeos de equinos adultos são os Cyathostominae (small strongyles) e Strongylus vulgaris (large strongyle). S. vulgaris é mais patogênico, causando arterite mesentérica e cólica. A vermifugação estratégica é essencial.`},{id:`cga-111`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Carrapato bovino`,dificuldade:`basico`,enunciado:`O carrapato dos bovinos, Rhipicephalus microplus, é o principal ectoparasita de bovinos no Brasil. O controle inclui:`,alternativas:[`Apenas banho com carrapaticidas.`,`Manejo integrado: carrapaticidas (banho, pour-on, injetáveis), controle biológico, manejo de pastagens e seleção genética de animais resistentes.`,`Apenas vacinação.`,`Apenas controle biológico.`,`Apenas manejo de pastagens.`],resposta_correta:`B`,explicacao:`O controle do carrapato bovino deve ser integrado: carrapaticidas (banho, pour-on, injetáveis), controle biológico (fungos entomopatogênicos, parasitoides), manejo de pastagens (rotação) e seleção genética de animais resistentes.`},{id:`cga-112`,banca:`UFMG`,ano:2022,prova:`UFMG — Concurso 2022`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Coccidiose em bovinos`,dificuldade:`medio`,enunciado:`A coccidiose em bovinos, causada por Eimeria spp., acomete principalmente:`,alternativas:[`Animais adultos em pastejo.`,`Bezerros e novilhos em confinamento ou lotação excessiva, causando diarreia hemorrágica e tenesmo.`,`Vacas em lactação.`,`Touros em reprodução.`,`Animais idosos.`],resposta_correta:`B`,explicacao:`A coccidiose acomete bezerros e novilhos (1-24 meses), especialmente em condições de confinamento ou lotação excessiva. Os sinais incluem diarreia (com muco e sangue), tenesmo, desidratação e perda de peso. As espécies mais patogênicas são E. zuernii e E. bovis.`},{id:`cga-113`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso 2021`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Estrongilídeo pulmonar`,dificuldade:`medio`,enunciado:`A verminose pulmonar em bovinos e ovinos, causada por Dictyocaulus viviparus e D. filaria, respectivamente, apresenta:`,alternativas:[`Diarreia crônica e perda de peso.`,`Tosse, dispneia, corrimento nasal e retardo de crescimento.`,`Artrite e edema articular.`,`Dermatite e prurido.`,`Icterícia e hemoglobinúria.`],resposta_correta:`B`,explicacao:`Os estrongilídeos pulmonares causam bronquite e pneumonia verminótica, com tosse, dispneia, corrimento nasal e retardo de crescimento. O diagnóstico é pela técnica de Baermann (larvas nas fezes).`},{id:`cga-114`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Miíases`,dificuldade:`basico`,enunciado:`As miíases (bicheiras) em grandes animais são causadas por larvas de dípteros. A miíase mais comum em bovinos é:`,alternativas:[`Cochliomyia hominivorax (mosca-varejeira).`,`Dermatobia hominis (mosca-do-berne).`,`Lucilia sericata (mosca-da-lã).`,`Wohlfahrtia magnifica.`,`Oestrus ovis.`],resposta_correta:`B`,explicacao:`A mosca-do-berne (Dermatobia hominis) é a causa mais comum de miíase em bovinos no Brasil. As larvas se desenvolvem em nódulos subcutâneos. O tratamento é com larvicidas tópicos ou remoção manual das larvas.`},{id:`cga-115`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso 2023`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Parascaris equorum`,dificuldade:`basico`,enunciado:`A infecção por Parascaris equorum em equinos acomete principalmente:`,alternativas:[`Animais adultos.`,`Potros de 3-12 meses de idade, causando cólica, obstrução intestinal e retardo de crescimento.`,`Cavalos de esporte em treinamento.`,`Éguas em lactação.`,`Equinos idosos.`],resposta_correta:`B`,explicacao:`Parascaris equorum acomete potros de 3-12 meses de idade. As larvas migram pelo fígado e pulmões antes de se estabelecerem no intestino delgado. Causam cólica, obstrução intestinal (em infestações massivas) e retardo de crescimento.`},{id:`cga-116`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Agropecuário 2022`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`FAMACHA`,dificuldade:`basico`,enunciado:`O sistema FAMACHA é utilizado para:`,alternativas:[`Diagnóstico de mastite.`,`Avaliação do grau de anemia em ovinos e caprinos infectados por Haemonchus contortus, pela coloração da conjuntiva ocular.`,`Diagnóstico de tuberculose.`,`Avaliação do escore corporal.`,`Diagnóstico de brucelose.`],resposta_correta:`B`,explicacao:`O sistema FAMACHA avalia a coloração da conjuntiva ocular (escala de 1 a 5) para estimar o grau de anemia em ovinos e caprinos infectados por H. contortus. Animais com escores 4 e 5 (mucosas brancas) devem ser tratados.`},{id:`cga-117`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso 2021`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Babesiose bovina`,dificuldade:`medio`,enunciado:`A babesiose bovina, causada por Babesia bovis e B. bigemina, é transmitida por:`,alternativas:[`Mosquitos Culex.`,`Carrapato Rhipicephalus microplus.`,`Moscas estáveis (Stomoxys calcitrans).`,`Flebotomíneos.`,`Carrapatos Ixodes.`],resposta_correta:`B`,explicacao:`A babesiose bovina é transmitida pelo carrapato Rhipicephalus microplus. B. bigemina é transmitida na fase adulta do carrapato e B. bovis na fase larvar. Os sinais incluem febre alta, anemia hemolítica, icterícia e hemoglobinúria.`},{id:`cga-118`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Escaravelho estercal`,dificuldade:`basico`,enunciado:`O papel ecológico dos escaravelhos estercais (dung beetles) na pecuária é:`,alternativas:[`Transmitir doenças parasitárias.`,`Fragmentar e enterrar os estercos, reduzindo a população de moscas, melhorando a ciclagem de nutrientes e reduzindo a contaminação das pastagens por parasitas.`,`Alimentar-se de carrapatos.`,`Produzir toxinas no solo.`,`Nenhum papel ecológico relevante.`],resposta_correta:`B`,explicacao:`Os escaravelhos estercais desempenham papel ecológico importante na pecuária: fragmentam e enterram estercos, reduzem a população de moscas, melhoram a ciclagem de nutrientes no solo e reduzem a contaminação das pastagens por ovos e larvas de parasitas.`},{id:`cga-119`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Resistência anti-helmíntica`,dificuldade:`dificil`,enunciado:`A resistência aos anti-helmínticos em nematódeos gastrintestinais de ruminantes é um problema crescente. Sobre o manejo antiparasitário sustentável, é CORRETO:`,alternativas:[`Tratar todos os animais do rebanho simultaneamente a cada 30 dias.`,`Utilizar estratégias como tratamento seletivo (FAMACHA), rotação de princípios ativos, refúgio parasitário e dose correta por peso vivo.`,`Utilizar sempre o anti-helmíntico mais barato.`,`Aumentar a dose recomendada para garantir eficácia.`,`Não tratar os animais para manter o refúgio parasitário.`],resposta_correta:`B`,explicacao:`O manejo sustentável inclui: tratamento seletivo (FAMACHA para H. contortus), rotação de classes de anti-helmínticos, manutenção de refúgio parasitário (10-20% do rebanho não tratado), dose correta por pesagem dos animais e quarentena de animais comprados.`},{id:`cga-120`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Concurso 2022`,tipo:`concurso`,topico:`parasitoses_ga`,subtopico:`Habronemíase equina`,dificuldade:`medio`,enunciado:`A habronemíase (úlcera de verão) em equinos é causada por:`,alternativas:[`Habronema muscae e Draschia megastoma, cujas larvas depositadas por moscas causam lesões granulomatosas na pele e no estômago.`,`Parascaris equorum.`,`Strongylus vulgaris.`,`Oxyuris equi.`,`Dictyocaulus arnfieldi.`],resposta_correta:`A`,explicacao:`A habronemíase é causada por Habronema muscae, H. microstoma e Draschia megastoma. As larvas depositadas por moscas (Musca domestica, Stomoxys calcitrans) em feridas cutâneas causam lesões granulomatosas (úlcera de verão).`},{id:`cga-121`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Suplementação mineral`,dificuldade:`basico`,enunciado:`A suplementação mineral para bovinos em pastejo deve considerar:`,alternativas:[`Apenas sal comum (NaCl).`,`Macro e microminerais (P, Ca, Mg, S, Co, Cu, Zn, Se, Mn, I) de acordo com as exigências do NRC e a composição das forragens.`,`Apenas fósforo e cálcio.`,`Apenas minerais quando o animal apresenta sinais de deficiência.`,`A suplementação mineral é dispensável em pastagens tropicais.`],resposta_correta:`B`,explicacao:`A suplementação mineral deve ser formulada com base nas exigências do NRC e na composição mineral das forragens disponíveis. Os minerais mais deficientes em pastagens tropicais são P, Na, Cu, Zn e Se.`},{id:`cga-122`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Fibra efetiva`,dificuldade:`medio`,enunciado:`O conceito de fibra efetiva (peNDF) na nutrição de ruminantes refere-se:`,alternativas:[`Ao teor de fibra bruta na dieta.`,`À fração de fibra que estimula a ruminação e a salivação, mantendo o pH ruminal adequado.`,`Ao teor de celulose na forragem.`,`À quantidade de concentrado na dieta.`,`Ao teor de matéria seca do alimento.`],resposta_correta:`B`,explicacao:`A fibra efetiva (peNDF) é a fração da fibra que estimula a ruminação e a salivação, contribuindo para a manutenção do pH ruminal adequado (6,2-6,8). Dietas com baixa fibra efetiva predispoem à acidose ruminal.`},{id:`cga-123`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Pastagens tropicais`,dificuldade:`basico`,enunciado:`As pastagens tropicais mais utilizadas para bovinos no Brasil incluem:`,alternativas:[`Apenas alfafa e trevo.`,`Braquiária (Urochloa spp.), capim-elefante (Pennisetum purpureum), capim-tanzânia e Mombaça (Megathyrsus maximus).`,`Apenas capim-azevém e festuca.`,`Apenas soja e milho para pastejo.`,`Apenas pastagens nativas do Cerrado.`],resposta_correta:`B`,explicacao:`As principais pastagens tropicais no Brasil são Braquiária (Urochloa spp.), capim-elefante (Pennisetum purpureum), Mombaça e Tanzânia (Megathyrsus maximus) e Panicum maximum cv. Gatton.`},{id:`cga-124`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Proteína degradável no rúmen`,dificuldade:`dificil`,enunciado:`Na nutrição de ruminantes, a proteína da dieta é classificada em:`,alternativas:[`Apenas proteína bruta e proteína digestível.`,`Proteína degradável no rúmen (PDR) e proteína não degradável no rúmen (PNDR), sendo que a PDR é essencial para a síntese de proteína microbiana.`,`Apenas aminoácidos essenciais.`,`Proteína solúvel e proteína insolúvel.`,`Proteína animal e proteína vegetal.`],resposta_correta:`B`,explicacao:`A proteína da dieta para ruminantes é classificada em PDR (degradada no rúmen pelos microrganismos) e PNDR (passa para o intestino delgado sem degradação). A PDR é essencial para a síntese de proteína microbiana, que é a principal fonte de aminoácidos para o animal.`},{id:`cga-125`,banca:`UFMG`,ano:2022,prova:`UFMG — Concurso 2022`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Confinamento de bovinos`,dificuldade:`medio`,enunciado:`No confinamento de bovinos de corte, a adaptação ao concentrado deve ser:`,alternativas:[`Imediata, com 100% de concentrado desde o primeiro dia.`,`Gradual, ao longo de 14-21 dias, aumentando progressivamente a proporção de concentrado na dieta.`,`Necessária apenas para animais jovens.`,`Dispensável se o concentrado for de alta qualidade.`,`Feita em 3-5 dias.`],resposta_correta:`B`,explicacao:`A adaptação ao concentrado no confinamento deve ser gradual (14-21 dias), iniciando com 50-60% de volumoso e aumentando progressivamente a proporção de concentrado. Isso permite a adaptação da microbiota ruminal e previne acidose.`},{id:`cga-126`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Ureia na dieta de ruminantes`,dificuldade:`medio`,enunciado:`A ureia na dieta de ruminantes é:`,alternativas:[`Sempre tóxica e deve ser evitada.`,`Uma fonte de nitrogênio não proteico (NNP) que pode ser utilizada pelos microrganismos ruminais para síntese de proteína microbiana, quando fornecida corretamente.`,`Indicada apenas para ovinos.`,`Utilizada exclusivamente em dietas de confinamento.`,`Uma fonte de energia para os microrganismos ruminais.`],resposta_correta:`B`,explicacao:`A ureia é uma fonte de NNP que os microrganismos ruminais utilizam para sintetizar aminoácidos e proteína microbiana. Deve ser fornecida gradualmente e misturada ao concentrado. A dose máxima é de 1% da matéria seca da dieta.`},{id:`cga-127`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Escore corporal equino`,dificuldade:`basico`,enunciado:`O escore corporal (EC) em equinos é avaliado em uma escala de:`,alternativas:[`1 a 3.`,`1 a 5, com incrementos de 0,5.`,`1 a 10.`,`1 a 9.`,`0 a 5.`],resposta_correta:`B`,explicacao:`O escore corporal em equinos é avaliado pela escala de Henneke (1 a 5, com incrementos de 0,5), avaliando-se a deposição de gordura no pescoço, cernelha, costelas, lombo e cauda. EC 3 é considerado ideal para a maioria dos equinos.`},{id:`cga-128`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Deficiência de cobre`,dificuldade:`medio`,enunciado:`A deficiência de cobre em bovinos causa:`,alternativas:[`Apenas perda de peso.`,`Descoloração do pelo (achromatrichia), diarreia crônica, retardo de crescimento e osteodistrofia.`,`Dermatite e prurido.`,`Tosse e dispneia.`,`Artrite e edema articular.`],resposta_correta:`B`,explicacao:`A deficiência de cobre causa descoloração do pelo (principalmente ao redor dos olhos), diarreia crônica, retardo de crescimento, osteodistrofia e redução da fertilidade. É comum em solos arenosos e na presença de molibdênio excessivo.`},{id:`cga-129`,banca:`UFMT`,ano:2023,prova:`UFMT — Concurso 2023`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Deficiência de fósforo`,dificuldade:`basico`,enunciado:`A deficiência de fósforo em bovinos é a deficiência mineral mais comum no Brasil e causa:`,alternativas:[`Apenas diarreia.`,`Pica (depravação do apetite), retardo de crescimento, redução da fertilidade e osteodistrofia.`,`Tosse e dispneia.`,`Dermatite e prurido.`,`Artrite e edema articular.`],resposta_correta:`B`,explicacao:`A deficiência de fósforo é a mais comum no Brasil, causando pica (ingestão de ossos, madeira, terra), retardo de crescimento, redução da produção leiteira e da fertilidade, e osteodistrofia. Pastagens tropicais são naturalmente pobres em fósforo.`},{id:`cga-130`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Pastagem de aveia e azevém`,dificuldade:`basico`,enunciado:`As pastagens de inverno (aveia + azevém) no Sul do Brasil são importantes para:`,alternativas:[`Apenas produção de feno.`,`Suplementação alimentar no inverno, proporcionando ganho de peso superior em bovinos de corte e produção de leite.`,`Apenas produção de silagem.`,`Controle de plantas daninhas.`,`Nenhuma finalidade produtiva.`],resposta_correta:`B`,explicacao:`As pastagens de inverno (aveia + azevém) são fundamentais no Sul do Brasil para suplementação alimentar, proporcionando ganho de peso de 0,5-1,0 kg/dia em bovinos de corte e sustentando a produção de leite durante o inverno.`},{id:`cga-131`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário 2022`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Silagem de milho`,dificuldade:`medio`,enunciado:`A silagem de milho é a principal forragem conservada para bovinos. Sobre a qualidade da silagem, é CORRETO:`,alternativas:[`O ponto ideal de colheita é com 25-30% de MS.`,`O ponto ideal de colheita é com 30-35% de matéria seca (MS), e a compactação e vedação adequadas são essenciais para evitar perdas por fermentação aeróbia.`,`A fermentação anaeróbica não é necessária.`,`A silagem pode ser exposta ao ar por 48 horas sem perdas.`,`O tamanho de partícula não influencia a qualidade.`],resposta_correta:`B`,explicacao:`A silagem de milho deve ser colhida com 30-35% de MS para melhor fermentação. A compactação (600-700 kg/m³) e vedação são essenciais para criar ambiente anaeróbico. Exposição ao ar por mais de 24 horas causa perdas significativas por fermentação aeróbia.`},{id:`cga-132`,banca:`UFRPE`,ano:2022,prova:`UFRPE — Concurso 2022`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Sal mineral`,dificuldade:`basico`,enunciado:`O sal mineral para bovinos deve ser oferecido:`,alternativas:[`Apenas quando o animal apresenta sinais de deficiência.`,`Ad libitum (livre acesso), em cochos protegidos da chuva e sol, com formulação adequada para cada categoria animal.`,`Apenas no cocho de ração.`,`Misturado ao volumoso.`,`Apenas no período seco.`],resposta_correta:`B`,explicacao:`O sal mineral deve ser oferecido ad libitum em cochos protegidos da chuva e sol, com consumo médio de 80-100 g/animal/dia para bovinos adultos. A formulação deve ser ajustada para cada categoria (corte, leite, recria).`},{id:`cga-133`,banca:`UFBA`,ano:2023,prova:`UFBA — Concurso 2023`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Escore de condição corporal bovino`,dificuldade:`basico`,enunciado:`O escore de condição corporal (ECC) em bovinos é avaliado em escala de:`,alternativas:[`1 a 3.`,`1 a 5, com incrementos de 0,25 ou 0,5.`,`1 a 10.`,`1 a 9.`,`0 a 5.`],resposta_correta:`B`,explicacao:`O ECC em bovinos é avaliado em escala de 1 a 5 (muito magro a muito gordo), com incrementos de 0,25 ou 0,5. Avalia-se a deposição de gordura na cauda, costelas, lombo e processos espinhosos. ECC ideal para vacas de corte ao parto: 3,0-3,5.`},{id:`cga-134`,banca:`UFPR`,ano:2021,prova:`UFPR — Concurso 2021`,tipo:`concurso`,topico:`nutricao_ga`,subtopico:`Níveis de utilização`,dificuldade:`dificil`,enunciado:`Os Níveis de Utilização (NU) na nutrição de ruminantes classificam as dietas em:`,alternativas:[`Apenas manutenção e produção.`,`Manutenção, crescimento e engorda, lactação e reprodução, com exigências crescentes de energia e proteína.`,`Apenas volumoso e concentrado.`,`Apenas ração e pastagem.`,`Níveis de 1 a 10.`],resposta_correta:`B`,explicacao:`Os Níveis de Utilização (NU) classificam as dietas conforme a exigência animal: manutenção, crescimento/engorda, lactação e reprodução. Cada nível tem exigências crescentes de energia, proteína, minerais e vitaminas.`},{id:`cga-135`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Ciclo estral bovino`,dificuldade:`basico`,enunciado:`O ciclo estral de vacas tem duração média de:`,alternativas:[`10-14 dias.`,`18-24 dias (média de 21 dias).`,`25-30 dias.`,`7-10 dias.`,`28-35 dias.`],resposta_correta:`B`,explicacao:`O ciclo estral bovino tem duração média de 21 dias (18-24 dias). As fases são: proestro (2-3 dias), estro (12-18 horas), metaestro (3-4 dias) e diestro (12-14 dias). A ovulação ocorre 10-12 horas após o fim do estro.`},{id:`cga-136`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Inseminação artificial`,dificuldade:`medio`,enunciado:`A inseminação artificial (IA) em bovinos é realizada:`,alternativas:[`No momento do cio (estro), independentemente do tempo.`,`De 12 a 24 horas após o início do estro (ou 6-12 horas antes da ovulação), após observação de cio.`,`Apenas 48 horas após o cio.`,`No dia 21 do ciclo estral.`,`Apenas no pós-parto imediato.`],resposta_correta:`B`,explicacao:`A IA deve ser realizada 12-24 horas após o início do estro (ou 6-12 horas antes da ovulação), baseada na regra AM/PM: se o cio é observado pela manhã, inseminar à tarde; se observado à tarde, inseminar na manhã seguinte.`},{id:`cga-137`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Gestação bovina`,dificuldade:`basico`,enunciado:`A duração da gestação em bovinos é em média:`,alternativas:[`90-120 dias.`,`280-290 dias (aproximadamente 9 meses e 10 dias).`,`330-360 dias.`,`180-210 dias.`,`240-260 dias.`],resposta_correta:`B`,explicacao:`A gestação em bovinos dura em média 280-290 dias (aproximadamente 9 meses e 10 dias). Em zebuínos é ligeiramente mais longa (290-300 dias) que em taurinos.`},{id:`cga-138`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Diagnóstico de gestação`,dificuldade:`medio`,enunciado:`O diagnóstico de gestação em equinos é feito por:`,alternativas:[`Apenas palpação retal.`,`Ultrassonografia transretal (a partir de 14 dias) e palpação retal (a partir de 30-35 dias).`,`Dosagem hormonal em sangue (P4) exclusivamente.`,`Radiografia abdominal.`,`Exame clínico geral.`],resposta_correta:`B`,explicacao:`O diagnóstico de gestação em equinos é feito por ultrassonografia transretal (a partir de 14 dias pós-ovulação) e palpação retal (a partir de 30-35 dias). A ultrassonografia permite detectar gêmeos e avaliar a viabilidade embrionária.`},{id:`cga-139`,banca:`UFMG`,ano:2022,prova:`UFMG — Concurso 2022`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Parto bovino`,dificuldade:`basico`,enunciado:`As fases do parto em bovinos são:`,alternativas:[`Apenas expulsão fetal.`,`Preparação (dilatação do colo), expulsão do feto e expulsão das membranas fetais (secundinas).`,`Apenas dilatação e expulsão.`,`Contrações, dilatação e amamentação.`,`Dilatação, expulsão e involução uterina.`],resposta_correta:`B`,explicacao:`As três fases do parto em bovinos são: 1) Preparação (2-6 horas) - dilatação do colo uterino; 2) Expulsão (30 minutos a 4 horas) - saída do feto; 3) Secundinas (2-8 horas) - expulsão das membranas fetais.`},{id:`cga-140`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Infertilidade bovina`,dificuldade:`medio`,enunciado:`As principais causas de infertilidade em vacas de corte incluem:`,alternativas:[`Apenas problemas nutricionais.`,`Anestro pós-parto, baixo escore corporal, distúrbios infecciosos (campylobacteriose, tricomonose) e erros de manejo reprodutivo.`,`Apenas distúrbios genéticos.`,`Apenas idade avançada.`,`Apenas parasitismo.`],resposta_correta:`B`,explicacao:`As principais causas de infertilidade incluem anestro pós-parto (associado a baixo ECC), distúrbios infecciosos (campylobacteriose, tricomonose, brucelose), problemas nutricionais e erros de manejo (deteccão de cio inadequada).`},{id:`cga-141`,banca:`CESPE`,ano:2023,prova:`CESPE — Veterinário 2023`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Transferência de embriões`,dificuldade:`dificil`,enunciado:`A transferência de embriões (TE) em bovinos:`,alternativas:[`É realizada apenas em laboratório.`,`Consiste na coleta de embriões de doadoras superovuladas e transferência para receptoras sincronizadas, aumentando a produção de bezerras de alta genética.`,`Produz clones geneticamente idênticos.`,`Não requer sincronização de receptoras.`,`É uma técnica ultrapassada.`],resposta_correta:`B`,explicacao:`A TE consiste na superovulação da doadora com FSH, inseminação, coleta de embriões (7 dias pós-IA) e transferência para receptoras sincronizadas. A taxa de prenhez é de 50-60%. Permite multiplicar bezerras de alto valor genético.`},{id:`cga-142`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Sincronização de estro`,dificuldade:`medio`,enunciado:`Os protocolos de sincronização de estro em bovinos utilizam:`,alternativas:[`Apenas prostaglandina F2α (PGF2α).`,`Combinações de GnRH, PGF2α e progesterona (CIDR/Ovsynch) para sincular ovulações e permitir IA a tempo fixo.`,`Apenas GnRH.`,`Apenas progesterona.`,`Apenas estrógenos.`],resposta_correta:`B`,explicacao:`Os protocolos de IATF (inseminação artificial a tempo fixo) combinam GnRH, PGF2α e progesterona (CIDR) para sincronizar a ovulação. O protocolo Ovsynch (GnRH-7d-PGF-56h-GnRH-16h-IA) é o mais utilizado.`},{id:`cga-143`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Agropecuário 2022`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Gestação equina`,dificuldade:`basico`,enunciado:`A duração da gestação em equinos (cavalos) é em média:`,alternativas:[`280-290 dias.`,`320-360 dias (aproximadamente 11 meses).`,`150-180 dias.`,`400-420 dias.`,`240-260 dias.`],resposta_correta:`B`,explicacao:`A gestação em equinos dura em média 320-360 dias (aproximadamente 11 meses). A idade gestacional pode ser estimada pelo tamanho do feto (CRL) na ultrassonografia precoce.`},{id:`cga-144`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Cio em éguas`,dificuldade:`medio`,enunciado:`O estro (cio) em éguas tem duração média de:`,alternativas:[`12-24 horas.`,`5-7 dias (período de receptividade ao garanhão).`,`10-14 dias.`,`2-3 dias.`,`18-21 dias.`],resposta_correta:`B`,explicacao:`O estro em éguas dura em média 5-7 dias. O ciclo estral é de 21-23 dias. As éguas são poliéstricas sazonais (primavera-verão), com atividade ovariana dependente do fotoperíodo.`},{id:`cga-145`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário 2023`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Distocia`,dificuldade:`medio`,enunciado:`A distocia em bovinos é definida como:`,alternativas:[`Qualquer parto que dura mais de 1 hora.`,`Parto difícil que requer assistência para a expulsão do feto, causada por problemas maternos, fetais ou ambos.`,`Parto de gêmeos.`,`Retenção de placenta.`,`Parto prematuro.`],resposta_correta:`B`,explicacao:`A distocia é o parto difícil que requer assistência. As causas incluem problemas maternos (insuficiência de dilatação, torção uterina), fetais (apresentação anormal, hidrocefalia) e mistos (incompatibilidade feto-pélvica).`},{id:`cga-146`,banca:`UFMT`,ano:2022,prova:`UFMT — Concurso 2022`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Puberdade em bovinos`,dificuldade:`basico`,enunciado:`A puberdade em novilhas de corte é atingida quando:`,alternativas:[`Atingem 6 meses de idade.`,`Atingem 60-65% do peso adulto e idade adequada (12-18 meses em raças taurinas).`,`Atingem 100% do peso adulto.`,`Apenas com tratamento hormonal.`,`Não depende do peso.`],resposta_correta:`B`,explicacao:`A puberdade em novilhas de corte é atingida quando atingem 60-65% do peso adulto (280-320 kg em raças taurinas), geralmente entre 12-18 meses. O manejo nutricional adequado é essencial para antecipar a puberdade.`},{id:`cga-147`,banca:`UFRGS`,ano:2023,prova:`UFRGS — Concurso 2023`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Aborto infeccioso`,dificuldade:`medio`,enunciado:`As principais causas infecciosas de aborto em bovinos incluem:`,alternativas:[`Apenas brucelose.`,`Brucelose, leptospirose, neosporose, IBR/BHV-1 e BVD.`,`Apenas mastite.`,`Apenas parasitismo.`,`Apenas deficiências nutricionais.`],resposta_correta:`B`,explicacao:`As principais causas infecciosas de aborto em bovinos são: Brucella abortus (brucelose), Leptospira spp. (leptospirose), Neospora caninum (neosporose), BHV-1 (IBR) e BVDV (BVD). O diagnóstico requer envio de material ao laboratório.`},{id:`cga-148`,banca:`UFBA`,ano:2021,prova:`UFBA — Concurso 2021`,tipo:`concurso`,topico:`reproducao_ga`,subtopico:`Puerpério bovino`,dificuldade:`basico`,enunciado:`O puerpério em bovinos é o período que vai do parto até a involução uterina completa, com duração média de:`,alternativas:[`7-10 dias.`,`30-40 dias (involução uterina completa).`,`90-120 dias.`,`5-7 dias.`,`60-90 dias.`],resposta_correta:`B`,explicacao:`O puerpério em bovinos dura em média 30-40 dias, quando ocorre a involução uterina completa. O retorno ao cio (pós-parto) ocorre em média 40-60 dias em vacas de corte e 30-45 dias em vacas leiteiras, dependendo do ECC e manejo.`},{id:`cga-149`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Castração bovina`,dificuldade:`basico`,enunciado:`A castração em bovinos é realizada preferencialmente:`,alternativas:[`Em animais adultos acima de 3 anos.`,`Em animais jovens (6-12 meses), antes da puberdade, para reduzir o estresse cirúrgico e o sangramento.`,`Apenas em animais doentes.`,`Apenas no período de seca.`,`Em qualquer idade, sem restrições.`],resposta_correta:`B`,explicacao:`A castração é preferencialmente realizada em animais jovens (6-12 meses), antes da puberdade, quando o estresse cirúrgico é menor e o sangramento é mais controlado. Os métodos incluem bisturi, bisturi de Burdizzo (sem abertura de pele) e anel elástico.`},{id:`cga-150`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Desacornamento`,dificuldade:`medio`,enunciado:`O desacornamento em bovinos é indicado para:`,alternativas:[`Melhorar a produção de leite.`,`Prevenir ferimentos entre animais e facilitar o manejo, sendo realizado preferencialmente em bezerros até 2-3 meses de idade.`,`Tratar cornos infectados.`,`Melhorar a reprodução.`,`Apenas em animais adultos.`],resposta_correta:`B`,explicacao:`O desacornamento é indicado para prevenir ferimentos e facilitar o manejo. Em bezerros até 2-3 meses pode ser feito com pasta cáustica ou cauterizador elétrico. Em animais mais velhos, é necessária a remoção cirúrgica.`},{id:`cga-151`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Rumenotomia`,dificuldade:`medio`,enunciado:`A rumenotomia em bovinos é indicada em:`,alternativas:[`Apenas timpanismo gasoso.`,`Corpos estranhos reticulares, impação ruminal, timpanismo espumoso refratário e remoção de bezoares.`,`Apenas para diagnóstico.`,`Apenas em vacas leiteiras.`,`Apenas para coleta de material ruminal.`],resposta_correta:`B`,explicacao:`A rumenotomia é indicada para remoção de corpos estranhos (arame, plástico), impação ruminal, timpanismo refratário e remoção de bezoares. A cirurgia é realizada em quadrúpede, sob sedação e anestesia local infiltrativa.`},{id:`cga-152`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Cesariana bovina`,dificuldade:`medio`,enunciado:`Na cesariana bovina, o acesso cirúrgico mais comum é:`,alternativas:[`Linha mediana ventral.`,`Flanco direito (fossa paralombar direita) ou ventrolateral, dependendo da posição do feto.`,`Flanco esquerdo.`,`Região inguinal.`,`Região costal.`],resposta_correta:`B`,explicacao:`Na cesariana bovina, o acesso mais comum é pelo flanco direito (fossa paralombar direita) ou ventrolateral. A escolha depende da posição fetal e da preferência do cirurgião. A anestesia é por epidural e bloqueio local.`},{id:`cga-153`,banca:`UFMG`,ano:2022,prova:`UFMG — Residência 2022`,tipo:`residencia`,topico:`cirurgia_ga`,subtopico:`Herniorrafia umbilical`,dificuldade:`medio`,enunciado:`A hérnia umbilical em bovinos é tratada por:`,alternativas:[`Apenas observação.`,`Herniorrafia cirúrgica (redução do conteúdo herniárioe fechamento do anel herniário) quando o anel é grande ou há risco de estrangulamento.`,`Apenas antibioticoterapia.`,`Tratamento clínico com anti-inflamatórios.`,`Descarte do animal.`],resposta_correta:`B`,explicacao:`A hérnia umbilical é tratada cirurgicamente quando o anel herniário é grande (>2 cm) ou há risco de estrangulamento. A cirurgia consiste na redução do conteúdo herniário e fechamento do anel com sutura.`},{id:`cga-154`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Queratoplastia bovina`,dificuldade:`dificil`,enunciado:`A úlcera de córnea profunda em bovinos pode ser tratada com:`,alternativas:[`Apenas antibioticoterapia tópica.`,`Queratoplastia (enxerto de córnea), membrana nictitante flap ou sutura de terceira pálpebra para proteção.`,`Apenas enucleação.`,`Apenas colírios anti-inflamatórios.`,`Descarte do animal.`],resposta_correta:`B`,explicacao:`Úlceras corneanas profundas em bovinos requerem procedimentos cirúrgicos: queratoplastia (enxerto de córnea), flap de membrana nictitante ou sutura de terceira pálpebra para proteção. O tratamento clínico é complementar.`},{id:`cga-155`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Castração equina`,dificuldade:`basico`,enunciado:`A castração em equinos é realizada:`,alternativas:[`Apenas em campo, sem contenção.`,`Em contenção adequada (quadrúpede ou decúbito lateral), sob sedação e anestesia local ou geral, com técnica aberta ou fechada.`,`Apenas em hospital veterinário.`,`Apenas com anestesia geral.`,`Em qualquer idade, sem preparo.`],resposta_correta:`B`,explicacao:`A castração equina é realizada em contenção adequada, sob sedação (xilazina + detomidina) e anestesia local ou geral. As técnicas incluem aberta (com emasculador), fechada (com sutura do funículo) e semiaberta.`},{id:`cga-156`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Oftalmologia equina`,dificuldade:`medio`,enunciado:`A úlcera de córnea em equinos é uma emergência oftalmológica. O tratamento inclui:`,alternativas:[`Apenas antibioticoterapia sistêmica.`,`Antibioticoterapia tópica (ciprofloxacino, tobramicina), atropina para midriase e anti-inflamatórios. Evitar corticoides tópicos em úlceras infecciosas.`,`Corticoides tópicos em todos os casos.`,`Apenas cirurgia.`,`Descarte do animal.`],resposta_correta:`B`,explicacao:`O tratamento da úlcera corneana em equinos inclui antibióticos tópicos (ciprofloxacino, tobramicina), atropina para midriase (prevenir sinequias) e anti-inflamatórios sistêmicos. Corticoides tópicos são contraindicados em úlceras infecciosas.`},{id:`cga-157`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Agropecuário 2022`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Cirurgia de deslocamento de abomaso`,dificuldade:`dificil`,enunciado:`As técnicas cirúrgicas para correção do DAE em vacas leiteiras incluem:`,alternativas:[`Apenas omentopexia.`,`Toggle pin (fixação percutânea), omentopexia (fixação do omento à parede abdominal) e abomasopexia.`,`Apenas tratamento clínico.`,`Apenas abomasopexia.`,`Rumenotomia.`],resposta_correta:`B`,explicacao:`As técnicas para correção do DAE incluem: toggle pin (fixação percutânea com pino e sutura), omentopexia (fixação do omento à parede abdominal direita por laparotomia) e abomasopexia (fixação do abomaso à parede).`},{id:`cga-158`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Anestesia equina`,dificuldade:`medio`,enunciado:`A anestesia geral em equinos para procedimentos cirúrgicos é realizada preferencialmente por:`,alternativas:[`Máscara com isoflurano.`,`Indução IV (xilazina + cetamina + diazepam) e manutenção com isoflurano em circuito inalatório (insuflação endotraqueal).`,`Anestesia local em todos os casos.`,`Anestesia epidural para todos os procedimentos.`,`Sedação profunda com xilazina.`],resposta_correta:`B`,explicacao:`A anestesia geral em equinos é realizada por indução IV (pré-medicação com xilazina, indução com cetamina ± diazepam) e manutenção com isoflurano em circuito inalatório via tubo endotraqueal. A recuperação é assistida.`},{id:`cga-159`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Sutura de tendão`,dificuldade:`dificil`,enunciado:`A ruptura do tendão flexor digital profundo em equinos é tratada por:`,alternativas:[`Apenas imobilização.`,`Tenorrafia (sutura do tendão) e imobilização prolongada, ou desmotomia do ligamento sesamoideano distal em casos crônicos.`,`Descarte do animal.`,`Apenas anti-inflamatórios.`,`Exercício controlado imediato.`],resposta_correta:`B`,explicacao:`A ruptura do tendão flexor profundo pode ser tratada cirurgicamente com tenorrafia (sutura do tendão) e imobilização prolongada. Em casos crônicos com hiperextensão, a desmotomia do ligamento sesamoideano distal pode ser indicada.`},{id:`cga-160`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Concurso 2022`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Odontologia equina`,dificuldade:`basico`,enunciado:`O desgaste dentário (odontoplastia) em equinos é indicado para:`,alternativas:[`Apenas animais de esporte.`,`Remover pontas esmalantes que causam ferimentos na mucosa oral, melhorar a mastigação e o conforto do animal.`,`Apenas animais idosos.`,`Tratar cáries dentárias.`,`Apenas em potros.`],resposta_correta:`B`,explicacao:`A odontoplastia é indicada para remover pontas esmalantes (nos dentes pré-molares e molares) que causam ferimentos na mucosa oral, dificuldade de mastigação e desconforto. Deve ser feita anualmente em equinos adultos.`},{id:`cga-161`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_ga`,subtopico:`Castração por Burdizzo`,dificuldade:`basico`,enunciado:`O castrador de Burdizzo é utilizado para:`,alternativas:[`Remover os testículos cirurgicamente.`,`Esmagar o funículo espermático (sem abertura de pele), causando isquemia e atrofia testicular.`,`Cortar a pele do escroto.`,`Ligar os vasos sanguíneos.`,`Aplicar anel elástico.`],resposta_correta:`B`,explicacao:`O castrador de Burdizzo esmaga o funículo espermático (artéria e veia testiculares e ducto deferente) sem abertura de pele, causando isquemia e atrofia testicular. É um método de castração sem sangramento, preferido em animais jovens.`},{id:`cga-162`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Vacinação bovina`,dificuldade:`basico`,enunciado:`O calendário vacinal básico para bovinos de corte no Brasil inclui:`,alternativas:[`Apenas febre aftosa.`,`Febre aftosa, clostridioses (polivalente), brucelose (fêmeas 3-8 meses), raiva e IBR/BVD/DVB.`,`Apenas brucelose.`,`Apenas raiva.`,`Apenas clostridioses.`],resposta_correta:`B`,explicacao:`O calendário vacinal básico inclui: febre aftosa (semestral), clostridioses (anual), brucelose (fêmeas 3-8 meses com B19 ou RB51), raiva (anual) e IBR/BVD/DVB (conforme protocolo). A vacinação é regulamentada pelo MAPA.`},{id:`cga-163`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Vermifugação estratégica`,dificuldade:`medio`,enunciado:`A vermifugação estratégica em bovinos deve considerar:`,alternativas:[`Tratar todos os animais a cada 30 dias.`,`Monitorar a carga parasitária (EPG), tratar seletivamente e considerar o período do ano (pastos infectados, estação de pastejo).`,`Apenas tratar animais com diarreia.`,`Não vermifugar para manter a imunidade.`,`Utilizar sempre o mesmo anti-helmíntico.`],resposta_correta:`B`,explicacao:`A vermifugação estratégica baseia-se no monitoramento (EPG), tratamento seletivo (FAMACHA para Haemonchus), consideração do período do ano e rotação de princípios ativos. Animais com EPG alto ou sinais clínicos devem ser tratados.`},{id:`cga-164`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Controle de ectoparasitas`,dificuldade:`basico`,enunciado:`O controle de carrapatos em bovinos inclui:`,alternativas:[`Apenas banho carrapaticida.`,`Manejo integrado: carrapaticidas (banho, pour-on, injetáveis), controle biológico, manejo de pastagens e seleção genética.`,`Apenas vacinação.`,`Apenas controle biológico.`,`Apenas manejo de pastagens.`],resposta_correta:`B`,explicacao:`O controle de carrapatos deve ser integrado: carrapaticidas (banho, pour-on, injetáveis), controle biológico (fungos, parasitoides), manejo de pastagens (rotação) e seleção genética de animais resistentes.`},{id:`cga-165`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Biosseguridade`,dificuldade:`medio`,enunciado:`A biosseguridade em propriedades rurais inclui:`,alternativas:[`Apenas vacinação.`,`Quarentena de animais comprados, controle de acesso, desinfecção de veículos e equipamentos, manejo sanitário e monitoramento de doenças.`,`Apenas controle de acesso.`,`Apenas desinfecção.`,`Apenas quarentena.`],resposta_correta:`B`,explicacao:`A biosseguridade é o conjunto de medidas que previnem a entrada e disseminação de doenças: quarentena de animais novos, controle de acesso de pessoas e veículos, desinfecção, manejo sanitário adequado e monitoramento de doenças.`},{id:`cga-166`,banca:`UFMG`,ano:2022,prova:`UFMG — Concurso 2022`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Tratamento de vaca seca`,dificuldade:`medio`,enunciado:`O tratamento de vaca seca (dry cow therapy) consiste em:`,alternativas:[`Tratar todas as vacas com antibióticos durante a lactação.`,`Infusão intramamária de antibióticos de longa ação no momento do secamento para curar infecções existentes e prevenir novas infecções durante o período seco.`,`Apenas retirar o leite.`,`Não tratar vacas secas.`,`Apenas usar anti-inflamatórios.`],resposta_correta:`B`,explicacao:`O dry cow therapy consiste na infusão intramamária de antibióticos de longa ação no momento do secamento, para curar infecções subclínicas existentes e prevenir novas infecções durante o período seco. É uma das práticas mais importantes do controle de mastite.`},{id:`cga-167`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Vacinação equina`,dificuldade:`basico`,enunciado:`O calendário vacinal básico para equinos inclui:`,alternativas:[`Apenas raiva.`,`Influenza equina, tétano, encefalomielite (EEE/WEE/VEE) e raiva.`,`Apenas tétano.`,`Apenas influenza.`,`Apenas encefalomielite.`],resposta_correta:`B`,explicacao:`O calendário vacinal básico para equinos inclui: influenza equina, tétano, encefalomielite equina (EEE/WEE/VEE) e raiva. A vacinação de potros inicia-se aos 3-6 meses com reforços semestrais ou anuais.`},{id:`cga-168`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Controle de moscas`,dificuldade:`basico`,enunciado:`O controle de moscas em propriedades rurais inclui:`,alternativas:[`Apenas inseticidas.`,`Manejo integrado: higiene de instalações, controle biológico (vespinhas parasitoides), armadilhas, inseticidas e manejo de estercos.`,`Apenas armadilhas.`,`Apenas controle biológico.`,`Apenas higiene.`],resposta_correta:`B`,explicacao:`O controle de moscas deve ser integrado: higiene de instalações, controle biológico (vespinhas parasitoides como Spalangia spp.), armadilhas (luminosas, de CO₂), inseticidas e manejo adequado de estercos e dejetos.`},{id:`cga-169`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Identificação animal`,dificuldade:`basico`,enunciado:`A identificação individual de bovinos no Brasil é feita por:`,alternativas:[`Apenas marcação a fogo.`,`Brinco eletrônico (SISBOV) e/ou marcação auricular, conforme regulamentação do MAPA.`,`Apenas tatuagem.`,`Apenas colar.`,`Apenas marcação a frio.`],resposta_correta:`B`,explicacao:`A identificação individual de bovinos é feita por brinco eletrônico (SISBOV) e/ou marcação auricular, conforme regulamentação do MAPA. A rastreabilidade é obrigatória para exportação de carne.`},{id:`cga-170`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal Agropecuário 2023`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Vacinação contra febre aftosa`,dificuldade:`medio`,enunciado:`A vacinação contra febre aftosa no Brasil é:`,alternativas:[`Opcional para todas as regiões.`,`Obrigatória em regiões com vacinação (todo o país, exceto área livre sem vacinação), com vacinação semestral de bovinos e bubalinos.`,`Apenas para bovinos de exportação.`,`Apenas para animais em áreas de risco.`,`Apenas para bezerros.`],resposta_correta:`B`,explicacao:`A vacinação contra febre aftosa é obrigatória nas regiões com vacinação (todo o Brasil, exceto os estados do Paraná e Santa Catarina que são área livre sem vacinação), com vacinação semestral de bovinos e bubalinos de todas as idades.`},{id:`cga-171`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Controle de brucelose`,dificuldade:`medio`,enunciado:`O Programa Nacional de Controle e Erradicação da Brucelose e Tuberculose (PNCEBT) prevê:`,alternativas:[`Apenas vacinação.`,`Vacinação de fêmeas (3-8 meses) com B19 ou RB51, diagnóstico sorológico e descarte de reatores.`,`Apenas diagnóstico.`,`Apenas descarte de animais doentes.`,`Tratamento dos animais positivos.`],resposta_correta:`B`,explicacao:`O PNCEBT prevê: vacinação obrigatória de fêmeas bovinas e bubalinas (3-8 meses) com B19 ou RB51, diagnóstico sorológico em rebanhos e descarte dos animais reatores. O objetivo é erradicar a brucelose.`},{id:`cga-172`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso 2022`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Manejo sanitário de suínos`,dificuldade:`medio`,enunciado:`O manejo sanitário de suínos em granjas inclui:`,alternativas:[`Apenas vacinação.`,`All-in/all-out, vazio sanitário, controle de insetos e roedores, desinfecção de baias e controle de tráfego de pessoas.`,`Apenas antibioticoterapia.`,`Apenas desinfecção.`,`Apenas controle de insetos.`],resposta_correta:`B`,explicacao:`O manejo sanitário em granjas de suínos inclui: sistema all-in/all-out (por lotes), vazio sanitário entre lotes, controle de insetos e roedores, desinfecção de baias e controle de tráfego de pessoas.`},{id:`cga-173`,banca:`UFRGS`,ano:2023,prova:`UFRGS — Concurso 2023`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Quarentena`,dificuldade:`basico`,enunciado:`O período de quarentena para animais recém-adquiridos é recomendado de:`,alternativas:[`3-5 dias.`,`21-30 dias, com exames diagnósticos e observação clínica antes de introduzir no rebanho.`,`Apenas 7 dias.`,`Não é necessário quarentena.`,`90-120 dias.`],resposta_correta:`B`,explicacao:`O período de quarentena recomendado é de 21-30 dias, durante o qual os animais recém-adquiridos são observados clinicamente e submetidos a exames diagnósticos antes de serem introduzidos no rebanho.`},{id:`cga-174`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso 2021`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Controle de raiva`,dificuldade:`basico`,enunciado:`O controle da raiva em bovinos inclui:`,alternativas:[`Apenas vacinação antirrábica.`,`Vacinação anual, controle de morcegos hematófagos e notificação de casos suspeitos.`,`Apenas controle de morcegos.`,`Apenas notificação.`,`Tratamento dos animais infectados.`],resposta_correta:`B`,explicacao:`O controle da raiva em bovinos inclui: vacinação anual obrigatória, controle de morcegos hematófagos (Desmodus rotundus) e notificação imediata de casos suspeitos ao serviço veterinário oficial.`},{id:`cga-175`,banca:`UFPR`,ano:2022,prova:`UFPR — Concurso 2022`,tipo:`concurso`,topico:`manejo_sanitario_ga`,subtopico:`Desinfecção`,dificuldade:`basico`,enunciado:`Os desinfetantes mais utilizados em instalações pecuárias incluem:`,alternativas:[`Apenas água sanitária.`,`Compostos de amônio quaternário, hipoclorito de sódio, fenóis e formaldeído.`,`Apenas fenóis.`,`Apenas formaldeído.`,`Apenas iodóforos.`],resposta_correta:`B`,explicacao:`Os desinfetantes mais utilizados incluem compostos de amônio quaternário, hipoclorito de sódio, fenóis e formaldeído. A escolha depende do tipo de superfície, patógeno alvo e custo.`},{id:`cga-176`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Necropsia bovina`,dificuldade:`basico`,enunciado:`A necropsia de bovinos suspeitos de raiva deve incluir:`,alternativas:[`Apenas exame externo.`,`Coleta de encéfalo (hipocampo, cerebelo, bulbo) para diagnóstico por imunofluorescência direta.`,`Apenas exame do trato gastrintestinal.`,`Apenas coleta de sangue.`,`Exame de todos os órgãos, exceto o encéfalo.`],resposta_correta:`B`,explicacao:`Na necropsia de bovinos suspeitos de raiva, o encéfalo deve ser coletado (hipocampo, cerebelo, bulbo) para diagnóstico por imunofluorescência direta (IFD). O encéfalo deve ser refrigerado, não congelado.`},{id:`cga-177`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Lesões de enterotoxemia`,dificuldade:`medio`,enunciado:`Na necropsia de ovinos com enterotoxemia por Clostridium perfringens tipo D, as lesões características incluem:`,alternativas:[`Pneumonia fibrinosa.`,`Enterite necrosante, rins amolecidos ("pulpy kidney"), edema cerebral e hemorragias subepicárdicas.`,`Hepatomegalia e icterícia.`,`Dermatite e prurido.`,`Artrite e edema articular.`],resposta_correta:`B`,explicacao:`As lesões de enterotoxemia por C. perfringens tipo D incluem: enterite necrosante, rins amolecidos e edemaciados ("pulpy kidney"), edema e malacia cerebral, hemorragias subepicárdicas e mucosas.`},{id:`cga-178`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Diagnóstico laboratorial`,dificuldade:`medio`,enunciado:`O diagnóstico laboratorial de doenças infecciosas em grandes animais inclui:`,alternativas:[`Apenas hemograma.`,`Sorologia (ELISA, AGID, MAT), PCR, cultura bacteriológica, histopatologia e isolamento viral.`,`Apenas cultura.`,`Apenas PCR.`,`Apenas histopatologia.`],resposta_correta:`B`,explicacao:`O diagnóstico laboratorial inclui técnicas sorológicas (ELISA, AGID, MAT), biologia molecular (PCR), cultura bacteriológica, histopatologia e isolamento viral. A escolha depende da doença suspeita.`},{id:`cga-179`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Lesões de carbúnculo`,dificuldade:`medio`,enunciado:`Na necropsia de bovinos com carbúnculo hemático (Anthrax), as lesões características incluem:`,alternativas:[`Pneumonia fibrinosa.`,`Sangue não coagulado nos vasos, edema gelatinoso subcutâneo, esplenomegalia e hemorragias generalizadas.`,`Enterite necrosante.`,`Hepatite aguda.`,`Nefrite intersticial.`],resposta_correta:`B`,explicacao:`O carbúnculo hemático (Bacillus anthracis) apresenta: sangue escuro e não coagulado nos vasos, edema gelatinoso subcutâneo, esplenomegalia (baço em "geleia de ameixa"), hemorragias em serosas e mucosas. A necropsia é proibida.`},{id:`cga-180`,banca:`UFMG`,ano:2022,prova:`UFMG — Residência 2022`,tipo:`residencia`,topico:`patologia_ga`,subtopico:`Lesões de raiva`,dificuldade:`dificil`,enunciado:`O diagnóstico histopatológico da raiva em bovinos revela:`,alternativas:[`Corpúsculos de inclusão eosinofílicos (Corpúsculos de Negri) nos neurônios do hipocampo e cerebelo.`,`Lesões de encefalite purulenta.`,`Necrose neuronal sem inclusões.`,`Espongiose da substância branca.`,`Vasculite necrosante.`],resposta_correta:`A`,explicacao:`O diagnóstico histopatológico da raiva é baseado na presença de corpúsculos de inclusão eosinofílicos (Corpúsculos de Negri) nos neurônios do hipocampo e cerebelo. A IFD é mais sensível e específica.`},{id:`cga-181`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso 2021`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Coleta de material`,dificuldade:`basico`,enunciado:`Para diagnóstico de aborto infeccioso em bovinos, o material a ser coletado inclui:`,alternativas:[`Apenas sangue da mãe.`,`Estômago fetal (abomaso), placenta, fígado fetal, pulmão fetal e soros da mãe (pares).`,`Apenas leite.`,`Apenas fezes.`,`Apenas urina.`],resposta_correta:`B`,explicacao:`Para diagnóstico de aborto, deve-se coletar: abomaso fetal (conteúdo), placenta, fígado e pulmão fetal, e soros da mãe (pares soro convalescente). O material deve ser refrigerado e encaminhado ao laboratório.`},{id:`cga-182`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Lesões de clostridiose`,dificuldade:`medio`,enunciado:`As clostridioses em bovinos e ovinos causam lesões características. O carbúnculo sintomático (Clostridium chauvoei) apresenta:`,alternativas:[`Hepatite necrosante.`,`Mionecrose enfisematosa nos músculos esqueléticos (crepitação ao palpar).`,`Enterite necrosante.`,`Pneumonia fibrinosa.`,`Encefalite.`],resposta_correta:`B`,explicacao:`O carbúnculo sintomático (C. chauvoei) causa mionecrose enfisematosa nos músculos esqueléticos, com crepitação ao palpar, gás nos tecidos e necrose muscular. É mais comum em músculos dos membros e região torácica.`},{id:`cga-183`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso 2023`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Diagnóstico de tuberculose`,dificuldade:`medio`,enunciado:`O padrão-ouro para diagnóstico de tuberculose bovina é:`,alternativas:[`Intradermotuberculinização.`,`Cultivo em meio Löwenstein-Jensen com identificação da espécie por PCR.`,`ELISA.`,`Hemograma.`,`Radiografia torácica.`],resposta_correta:`B`,explicacao:`O padrão-ouro é o cultivo em meio Löwenstein-Jensen (ou Stonebrink) com identificação da espécie por PCR. A intradermotuberculinização é o teste de triagem oficial. O cultivo demora 8-12 semanas.`},{id:`cga-184`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Agropecuário 2022`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Patologia da febre aftosa`,dificuldade:`medio`,enunciado:`As lesões anatomopatológicas da febre aftosa em bovinos incluem:`,alternativas:[`Pneumonia intersticial.`,`Vesículas e erosões na cavidade oral, úbere e entre os dedos (coronetas).`,`Hepatite e icterícia.`,`Nefrite intersticial.`,`Encefalite.`],resposta_correta:`B`,explicacao:`As lesões da febre aftosa são vesículas (que se rompem formando erosões) na cavidade oral, úbere, coronetas e focinho. Em bezerros pode causar miocardite ("tigela de grama").`},{id:`cga-185`,banca:`UFMT`,ano:2023,prova:`UFMT — Concurso 2023`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Patologia da leptospirose`,dificuldade:`medio`,enunciado:`As lesões anatomopatológicas da leptospirose em bovinos incluem:`,alternativas:[`Pneumonia fibrinosa.`,`Icterícia, hemorragias pontilhadas em serosas (tela eczematosa), nefrite intersticial e hepatite.`,`Enterite necrosante.`,`Dermatite e prurido.`,`Artrite e edema articular.`],resposta_correta:`B`,explicacao:`As lesões da leptospirose incluem: icterícia, hemorragias pontilhadas em serosas (tela eczematosa), nefrite intersticial (rins aumentados com pontos brancos), hepatite e edema pulmonar.`},{id:`cga-186`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Histopatologia`,dificuldade:`medio`,enunciado:`A fixação de tecidos para histopatologia é feita em:`,alternativas:[`Soro fisiológico.`,`Formol tamponado 10% (formaldeído 37% diluído em água, tamponado com fosfato).`,`Álcool etílico 70%.`,`Água destilada.`,`Líquido de Bouin.`],resposta_correta:`B`,explicacao:`A fixação de tecidos para histopatologia é feita em formol tamponado 10%. A proporção é de 10:1 (volume de formol:volume de tecido). O tempo de fixação é de 24-48 horas.`},{id:`cga-187`,banca:`UFRGS`,ano:2021,prova:`UFRGS — Concurso 2021`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Necropsia de equinos`,dificuldade:`basico`,enunciado:`A necropsia de equinos deve ser realizada:`,alternativas:[`Apenas em animais mortos há mais de 24 horas.`,`O mais precocemente possível após a morte, antes da autólise comprometer as lesões.`,`Apenas em hospital veterinário.`,`Apenas quando há suspeita de raiva.`,`Em qualquer momento, sem restrições.`],resposta_correta:`B`,explicacao:`A necropsia deve ser realizada o mais precocemente possível após a morte, antes que a autólise e a decomposição comprometam a observação das lesões. Em equinos, a decomposição é rápida devido ao ceco volumoso.`},{id:`cga-188`,banca:`UFBA`,ano:2023,prova:`UFBA — Concurso 2023`,tipo:`concurso`,topico:`patologia_ga`,subtopico:`Corpúsculos de inclusão`,dificuldade:`dificil`,enunciado:`Corpúsculos de inclusão intranucleares em hepatócitos são característicos de:`,alternativas:[`Raiva.`,`Herpesvírus bovino tipo 1 (IBR/BHV-1) ou Herpesvírus bovino tipo 5 (encefalite herpética).`,`Clostridium chauvoei.`,`Babesia bovis.`,`Anaplasma marginale.`],resposta_correta:`B`,explicacao:`Corpúsculos de inclusão intranucleares em hepatócitos são característicos de infecções por herpesvírus: BHV-1 (IBR) e BHV-5 (encefalite herpética). Na raiva, os corpúsculos de Negri são citoplasmáticos, em neurônios.`},{id:`cga-189`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`MAPA`,dificuldade:`basico`,enunciado:`O Ministério da Agricultura, Pecuária e Abastecimento (MAPA) é responsável por:`,alternativas:[`Apenas fiscalização de alimentos.`,`Defesa sanitária animal e vegetal, inspeção de produtos de origem animal e vegetal e defesa agropecuária.`,`Apenas fiscalização de agrotóxicos.`,`Apenas controle de pragas agrícolas.`,`Apenas registro de medicamentos veterinários.`],resposta_correta:`B`,explicacao:`O MAPA é responsável pela defesa sanitária animal e vegetal, inspeção de produtos de origem animal e vegetal, defesa agropecuária, registro de produtos veterinários e fiscalização de estabelecimentos.`},{id:`cga-190`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`SIF`,dificuldade:`basico`,enunciado:`O Serviço de Inspeção Federal (SIF) é responsável por:`,alternativas:[`Apenas fiscalização de granjas.`,`Inspeção e controle higiênico-sanitário de produtos de origem animal em estabelecimentos sob jurisdição federal.`,`Apenas fiscalização de leite.`,`Apenas controle de abatedouros.`,`Apenas registro de produtos.`],resposta_correta:`B`,explicacao:`O SIF é responsável pela inspeção e controle higiênico-sanitário de produtos de origem animal (carne, leite, ovos, mel) em estabelecimentos sob jurisdição federal. O selo SIF atesta a qualidade do produto.`},{id:`cga-191`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário 2021`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`Notificação compulsória`,dificuldade:`medio`,enunciado:`As doenças de notificação compulsória ao MAPA incluem:`,alternativas:[`Apenas febre aftosa.`,`Febre aftosa, raiva, brucelose, tuberculose, carbúnculo hemático, peste suína africana, entre outras.`,`Apenas brucelose.`,`Apenas tuberculose.`,`Apenas raiva.`],resposta_correta:`B`,explicacao:`As doenças de notificação compulsória incluem: febre aftosa, raiva, brucelose, tuberculose, carbúnculo hemático (Anthrax), peste suína africana, peste suína clássica, leucose enzoótica, entre outras. A notificação deve ser imediata.`},{id:`cga-192`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`Programa de erradicação`,dificuldade:`medio`,enunciado:`O Programa Nacional de Controle e Erradicação da Brucelose e Tuberculose Animal (PNCEBT) é regulamentado pela:`,alternativas:[`Lei 8.171/91.`,`Instrução Normativa MAPA nº 10/2013.`,`Decreto 24.548/34.`,`Portaria 93/98.`,`Instrução Normativa MAPA nº 50/2021.`],resposta_correta:`B`,explicacao:`O PNCEBT é regulamentado pela Instrução Normativa MAPA nº 10, de 3 de abril de 2013, que define as regras para o controle e erradicação da brucelose e tuberculose animal no Brasil.`},{id:`cga-193`,banca:`UFMG`,ano:2022,prova:`UFMG — Concurso 2022`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`Vigilância sanitária`,dificuldade:`medio`,enunciado:`A vigilância sanitária em alimentos de origem animal inclui:`,alternativas:[`Apenas inspeção post mortem.`,`Inspeção ante e post mortem, controle de resíduos, análise microbiológica e monitoramento de zoonoses.`,`Apenas análise microbiológica.`,`Apenas controle de resíduos.`,`Apenas monitoramento de zoonoses.`],resposta_correta:`B`,explicacao:`A vigilância sanitária inclui: inspeção ante e post mortem dos animais, controle de resíduos e contaminantes, análise microbiológica dos produtos e monitoramento de zoonoses.`},{id:`cga-194`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso 2021`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`Trânsito animal`,dificuldade:`medio`,enunciado:`O trânsito de animais no Brasil requer:`,alternativas:[`Apenas nota fiscal.`,`Guia de Trânsito Animal (GTA) emitida pelo serviço veterinário oficial, com vacinações e exames atualizados.`,`Apenas atestado de saúde.`,`Apenas autorização do proprietário.`,`Não há restrições ao trânsito.`],resposta_correta:`B`,explicacao:`O trânsito de animais requer Guia de Trânsito Animal (GTA) emitida pelo serviço veterinário oficial, com vacinações e exames atualizados conforme a legislação do estado de destino.`},{id:`cga-195`,banca:`CESPE`,ano:2020,prova:`CESPE — Veterinário 2020`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`Febre aftosa - status`,dificuldade:`medio`,enunciado:`O Brasil é reconhecido pela OIE como:`,alternativas:[`País com febre aftosa endêmica.`,`País livre de febre aftosa com vacinação (estados do Paraná e Santa Catarina são livres sem vacinação).`,`País livre de febre aftosa sem vacinação em todo o território.`,`País com febre aftosa erradicada.`,`País em processo de erradicação.`],resposta_correta:`B`,explicacao:`O Brasil é reconhecido como país livre de febre aftosa com vacinação. Os estados do Paraná e Santa Catarina são reconhecidos como livres sem vacinação. O país busca a erradicação total.`},{id:`cga-196`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal Agropecuário 2023`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`SISBOV`,dificuldade:`basico`,enunciado:`O Sistema Brasileiro de Identificação e Certificação de Origem Bovina e Bubalina (SISBOV) é:`,alternativas:[`Um sistema opcional de identificação.`,`Sistema de identificação individual e rastreabilidade de bovinos e bubalinos, obrigatório para exportação de carne.`,`Apenas um sistema de registro de propriedades.`,`Apenas um sistema de controle sanitário.`,`Apenas um sistema de certificação de qualidade.`],resposta_correta:`B`,explicacao:`O SISBOV é o sistema de identificação individual e rastreabilidade de bovinos e bubalinos, utilizando brinco eletrônico. É obrigatório para exportação de carne e para a cadeia produtiva certificada.`},{id:`cga-197`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Concurso 2022`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`Resíduos em alimentos`,dificuldade:`medio`,enunciado:`O Programa de Controle de Resíduos e Contaminantes (PNCRC) monitora:`,alternativas:[`Apenas resíduos de antibióticos.`,`Resíduos de medicamentos veterinários, contaminantes ambientais e agrotóxicos em produtos de origem animal.`,`Apenas agrotóxicos.`,`Apenas contaminantes ambientais.`,`Apenas metais pesados.`],resposta_correta:`B`,explicacao:`O PNCRC monitora resíduos de medicamentos veterinários (antibióticos, hormônios, anti-helmínticos), contaminantes ambientais (metais pesados, dioxinas) e agrotóxicos em produtos de origem animal (carne, leite, ovos, mel).`},{id:`cga-198`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso 2021`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`Programa Nacional de Vigilância dos Resíduos`,dificuldade:`medio`,enunciado:`O MAPA estabelece períodos de carência para medicamentos veterinários. O período de carência é:`,alternativas:[`O tempo que o medicamento fica no organismo do animal.`,`O intervalo mínimo entre a última aplicação do medicamento e o abate do animal ou coleta de produto (leite, ovos).`,`O tempo de validade do medicamento.`,`O tempo de tratamento recomendado.`,`O intervalo entre doses do medicamento.`],resposta_correta:`B`,explicacao:`O período de carência é o intervalo mínimo entre a última administração do medicamento veterinário e o abate do animal ou a coleta de produtos de origem animal (leite, ovos). É definido para garantir que os resíduos estejam abaixo do LMR.`},{id:`cga-199`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso 2022`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`Inspeção ante mortem`,dificuldade:`basico`,enunciado:`A inspeção ante mortem em abatedouros tem como objetivo:`,alternativas:[`Apenas verificar o peso do animal.`,`Avaliar o estado de saúde do animal antes do abate, identificar animais doentes ou suspeitos e garantir a aptidão para o abate.`,`Apenas verificar a identificação do animal.`,`Apenas avaliar o escore corporal.`,`Apenas controlar o fluxo de animais.`],resposta_correta:`B`,explicacao:`A inspeção ante mortem tem como objetivo avaliar o estado sanitário dos animais antes do abate, identificar animais doentes ou suspeitos, garantir a aptidão para o abate e proteger a saúde pública.`},{id:`cga-200`,banca:`UFRPE`,ano:2023,prova:`UFRPE — Concurso 2023`,tipo:`concurso`,topico:`legislacao_ga`,subtopico:`Legislação sanitária estadual`,dificuldade:`medio`,enunciado:`A defesa sanitária animal no Brasil é organizada em três níveis:`,alternativas:[`Apenas federal e estadual.`,`Federal (MAPA), estadual (órgãos estaduais de defesa agropecuária) e municipal (vigilância sanitária municipal).`,`Apenas federal.`,`Apenas estadual e municipal.`,`Federal, estadual e internacional (OIE).`],resposta_correta:`B`,explicacao:`A defesa sanitária animal é organizada em três níveis: federal (MAPA/SFA), estadual (órgãos estaduais de defesa agropecuária como CEASA, IAGRO, etc.) e municipal (vigilância sanitária municipal). A coordenação é compartilhada.`}],i={totalQuestoes:r.length,porBanca:Object.entries(r.reduce((e,t)=>(e[t.banca]=(e[t.banca]||0)+1,e),{})).map(([t,n])=>({banca:t,total:n,...e[t]})),porAno:Object.entries(r.reduce((e,t)=>(e[t.ano]=(e[t.ano]||0)+1,e),{})).map(([e,t])=>({ano:Number(e),total:t})).sort((e,t)=>t.ano-e.ano),porTopico:Object.entries(r.reduce((e,t)=>(e[t.topico]=(e[t.topico]||0)+1,e),{})).map(([e,t])=>({topico:e,nome:n[e]?.nome,total:t})),porDificuldade:Object.entries(r.reduce((e,t)=>(e[t.dificuldade]=(e[t.dificuldade]||0)+1,e),{})).map(([e,t])=>({dificuldade:e,total:t}))};export{e as BANCAS,i as ESTATISTICAS_BANCO,r as QUESTOES_CLINICA_GA,t as TIPOS_PROVA,n as TOPICOS_CLINICA_GA};